window.PQ_DATA = window.PQ_DATA || {};
window.PQ_DATA["intermediario"] = {"id":"intermediario","name":"Intermediário","icon":"🚀","color":"#5C6773","pdf":"2_PYTHON_INTERMEDIARIO.pdf","desc":"Lambda, NumPy, Pandas, datas e APIs, gráficos, arquivos, e-mail, SQL, Selenium e web scraping.","topics":[{"name":"Funções como parâmetro e lambda","short":"funções que recebem e criam funções","cdesc":"lambda, funções como argumento (map, sorted, key), closures e decoradores","groups":[["Argumentos",[["*args","vários posicionais (tupla)"],["**kwargs","vários nomeados (dicionário)"]]],["Funções curtas",[["lambda","lambda x: x * 2"],["Funções de 1ª classe","passar função como argumento"],["key=","sorted(lista, key=lambda x: x[1]) / max(..., key=...)"]]],["Avançado",[["Escopo","local, global e regra LEGB"],["Decoradores","@ envolve e estende uma função"]]]],"hot":["lambda é uma função de uma linha: lambda x: x * 1.1 — ideal para key= e map.","Funções são objetos: podem ser guardadas em variáveis, listas e passadas como parâmetro.","Type hints (def f(x: int) -> int) não mudam a execução, mas documentam e ajudam a IDE."],"trap":"Parâmetro padrão mutável (lista=[]) é criado uma vez só e acumula entre chamadas.","examples":[["args_kwargs.py","# *args -> tupla\ndef somar_tudo(*numeros):\n    return sum(numeros)\n\nprint(somar_tudo(1, 2, 3, 4))   # 10\n\n# **kwargs -> dicionário\ndef perfil(**dados):\n    for k, v in dados.items():\n        print(f\"{k}: {v}\")\n\nperfil(nome=\"Ana\", cidade=\"SP\")\n\n# Type hints\ndef area(base: float, altura: float) -> float:\n    return base * altura\n\n# Escopo\ncontador = 0\ndef incrementar():\n    global contador          # evite quando puder\n    contador += 1\nincrementar()\nprint(contador)              # 1"],["lambda_decorador.py","# lambda\ndobro = lambda x: x * 2\nprint(dobro(5))              # 10\n\npessoas = [(\"Ana\", 30), (\"Leo\", 22)]\npessoas.sort(key=lambda p: p[1])\nprint(pessoas)   # [('Leo', 22), ('Ana', 30)]\n\n# Função como argumento\ndef aplicar(func, valor):\n    return func(valor)\nprint(aplicar(str.upper, \"oi\"))   # OI\n\n# Decorador\nimport time\ndef cronometro(func):\n    def wrapper(*args, **kwargs):\n        ini = time.time()\n        res = func(*args, **kwargs)\n        print(f\"{func.__name__}: {time.time()-ini:.3f}s\")\n        return res\n    return wrapper\n\n@cronometro\ndef processar():\n    return sum(range(1_000_000))\n\nprocessar()"]],"ex":[{"t":"*args","p":"Crie <code>somar_tudo(*numeros)</code>.","s":"","sol":"def somar_tudo(*numeros):\n    return sum(numeros)","test":"assert somar_tudo(1, 2, 3) == 6 and somar_tudo() == 0","h":["*numeros vira uma tupla."]},{"t":"**kwargs","p":"Crie <code>perfil(**dados)</code>, que retorna o próprio dicionário recebido.","s":"","sol":"def perfil(**dados):\n    return dados","test":"assert perfil(nome=\"Ana\", cidade=\"SP\") == {\"nome\": \"Ana\", \"cidade\": \"SP\"}","h":["**dados vira um dicionário."]},{"t":"lambda","p":"Crie <code>dobro</code> como uma lambda.","s":"","sol":"dobro = lambda x: x * 2","test":"assert dobro(5) == 10 and dobro.__name__ == \"<lambda>\", \"Use lambda\"","h":["dobro = lambda x: ..."]},{"t":"Ordenar com lambda","p":"Ordene <code>pessoas</code> (nome, idade) pela idade decrescente em <code>ordenadas</code>.","s":"pessoas = [(\"Ana\", 30), (\"Leo\", 22), (\"Bia\", 41)]","sol":"ordenadas = sorted(pessoas, key=lambda p: p[1], reverse=True)","test":"assert ordenadas == [(\"Bia\", 41), (\"Ana\", 30), (\"Leo\", 22)]","h":["key=lambda p: p[1]"]},{"t":"Função como argumento","p":"Crie <code>aplicar(func, valor)</code>, que retorna func(valor).","s":"","sol":"def aplicar(func, valor):\n    return func(valor)","test":"assert aplicar(str.upper, \"oi\") == \"OI\" and aplicar(len, \"abc\") == 3","h":["Funções são objetos."]},{"t":"Função que retorna função","p":"Crie <code>multiplicador(n)</code>, que retorna uma função que multiplica por n.","s":"","sol":"def multiplicador(n):\n    def f(x):\n        return x * n\n    return f","test":"triplo = multiplicador(3)\nassert triplo(5) == 15 and multiplicador(2)(7) == 14","h":["Defina uma função interna e retorne-a."]},{"t":"Decorador","p":"Crie o decorador <code>maiusculo</code>, que converte em maiúsculas o texto retornado pela função decorada.","s":"","sol":"def maiusculo(func):\n    def wrapper(*args, **kwargs):\n        return func(*args, **kwargs).upper()\n    return wrapper","test":"@maiusculo\ndef ola(n):\n    return f\"olá {n}\"\nassert ola(\"ana\") == \"OLÁ ANA\"","h":["wrapper(*args, **kwargs) chama func e altera o retorno."]},{"t":"Closure com nonlocal","p":"Crie <code>criar_contador()</code>, que retorna uma função que, a cada chamada, retorna 1, 2, 3...","s":"","sol":"def criar_contador():\n    n = 0\n    def contar():\n        nonlocal n\n        n += 1\n        return n\n    return contar","test":"c = criar_contador()\nassert [c(), c(), c()] == [1, 2, 3]\nassert criar_contador()() == 1, \"Cada contador deve ser independente\"","h":["nonlocal n"]},{"t":"Type hints","p":"Crie <code>area(base: float, altura: float) -> float</code>.","s":"","sol":"def area(base: float, altura: float) -> float:\n    return base * altura","test":"assert area(2, 3) == 6\nassert area.__annotations__ == {\"base\": float, \"altura\": float, \"return\": float}, \"Inclua as anotações de tipo\"","h":["def f(x: float) -> float:"]},{"t":"map com lambda","p":"Aplique 10% de aumento em <code>precos</code> usando map e lambda. Guarde a lista em <code>novos</code> (round 2).","s":"precos = [10, 20, 5]","sol":"novos = list(map(lambda p: round(p * 1.1, 2), precos))","test":"assert novos == [11.0, 22.0, 5.5]","h":["map(lambda p: ..., precos)"]},{"t":"Recursão","p":"Crie <code>soma_lista(lista)</code> RECURSIVA.","s":"","sol":"def soma_lista(lista):\n    if not lista:\n        return 0\n    return lista[0] + soma_lista(lista[1:])","test":"assert soma_lista([1, 2, 3, 4]) == 10 and soma_lista([]) == 0","h":["Caso base: lista vazia.","lista[0] + soma_lista(lista[1:])"]},{"t":"Decorador contador","p":"Crie o decorador <code>contar_chamadas</code>, que guarda no atributo <code>wrapper.chamadas</code> quantas vezes a função foi chamada.","s":"","sol":"def contar_chamadas(func):\n    def wrapper(*args, **kwargs):\n        wrapper.chamadas += 1\n        return func(*args, **kwargs)\n    wrapper.chamadas = 0\n    return wrapper","test":"@contar_chamadas\ndef f():\n    return 1\nf(); f(); f()\nassert f.chamadas == 3","h":["Funções podem ter atributos: wrapper.chamadas = 0."]},{"t":"Armadilha do padrão mutável","p":"Crie <code>adicionar(item, lista=None)</code>, que cria uma nova lista quando nenhuma é passada.","s":"","sol":"def adicionar(item, lista=None):\n    if lista is None:\n        lista = []\n    lista.append(item)\n    return lista","test":"assert adicionar(1) == [1] and adicionar(2) == [2], \"Não use lista=[] como padrão\"","h":["Padrão None + criação dentro da função."]},{"t":"Compor funções","p":"Crie <code>compor(f, g)</code>, que retorna uma função que calcula f(g(x)).","s":"","sol":"def compor(f, g):\n    return lambda x: f(g(x))","test":"h = compor(lambda x: x + 1, lambda x: x * 2)\nassert h(5) == 11","h":["return lambda x: f(g(x))"]},{"t":"Desafio: memoização","p":"Use functools.lru_cache para criar <code>fib(n)</code> rápido (fib(0)=0, fib(1)=1).","s":"","sol":"from functools import lru_cache\n\n@lru_cache(maxsize=None)\ndef fib(n):\n    return n if n < 2 else fib(n - 1) + fib(n - 2)","test":"assert fib(10) == 55 and fib(80) == 23416728348467685","h":["@lru_cache(maxsize=None)"]}],"map":"chaves","src":"Intermediário • Módulo 20","origem":"reaproveitada"},{"name":"NumPy","short":"a base da análise de dados","cdesc":"arrays, operações vetorizadas, estatísticas, filtros com where e reshape com eixos","map":"radial","src":"Intermediário • Módulo 21","pkgs":["numpy"],"groups":[["Arrays",[["np.array([...])","sequência de valores do MESMO tipo"],["Lista × array","lista + 1 dá erro; array + 1 soma em todos"],["dtype","int64, float64, <U32 (texto)"]]],["Índices e fatias",[["a[0], a[-1]","como nas listas"],["a[1:4]","fim não incluso"],["a[a > 10]","filtro booleano"]]],["Funções",[["sum, max, min, mean","a.sum() ou np.sum(a)"],["argmax / argmin","POSIÇÃO do maior/menor"],["sort, dot","ordenar; produto escalar (unidades × preços)"]]],["Estatística e aleatórios",[["percentile, var, std","posição relativa e dispersão"],["rng = np.random.default_rng(42)","gerador com semente"],["rng.integers / rng.normal","números aleatórios"]]],["Condições",[["np.where(cond)","índices que atendem"],["np.where(cond, a, b)","escolhe valor por condição"],["& e |","and/or entre condições (use parênteses)"]]],["Forma",[["reshape(2, 7)","muda a forma (mesma quantidade)"],["ndim / shape","dimensões e tamanho"],["axis=0 / axis=1","ao longo das linhas / colunas"]]]],"hot":["Operações com array são aplicadas em TODOS os elementos de uma vez (vetorização).","argmax devolve a POSIÇÃO do maior valor, não o valor.","Condições combinadas usam & e | com parênteses: (a > 3) & (a < 8).","axis=0 percorre as linhas (resultado por coluna); axis=1 percorre as colunas (resultado por linha).","default_rng(seed) torna os aleatórios reprodutíveis para toda a equipe."],"trap":"Usar and/or com arrays dá erro (\"truth value is ambiguous\"). Use & e | com cada condição entre parênteses.","examples":[["numpy_basico.py","import numpy as np\n\nprecos = np.array([10.0, 25.5, 8.0, 40.0])\nprint(precos * 1.1)          # aumenta 10% em todos\nprint(precos.max(), precos.argmax())\n\nunidades = np.array([3, 1, 5, 2])\nprint(np.dot(unidades, precos))   # total vendido\n\nprint(precos[precos > 9])         # filtro booleano"],["numpy_analise.py","rng = np.random.default_rng(seed=42)\nvendas = rng.integers(100, 500, size=14)\n\nsemanas = vendas.reshape(2, 7)    # 2 semanas × 7 dias\nprint(semanas.sum(axis=1))        # total por semana\nprint(semanas.sum(axis=0))        # total por dia da semana\n\nsalarios = np.array([2500, 3800, 4200, 6000])\nprint(np.where(salarios > salarios.mean(), \"acima\", \"abaixo\"))\nprint(salarios[(salarios >= 3000) & (salarios <= 4500)])"]],"ex":[{"t":"Primeiro array","p":"Crie o array <code>precos</code> a partir da lista <code>lista_precos</code> e guarde em <code>tipo</code> o <code>dtype</code> como texto (<code>str(precos.dtype)</code>).","s":"import numpy as np\nlista_precos = [10.0, 25.5, 8.0]","sol":"precos = np.array(lista_precos)\ntipo = str(precos.dtype)","test":"assert isinstance(precos, np.ndarray), \"Use np.array(...)\"\nassert precos.tolist() == [10.0, 25.5, 8.0]\nassert tipo == \"float64\", \"dtype de números decimais: float64\"","h":["np.array(lista)","O tipo interno fica em .dtype"]},{"t":"Reajuste vetorizado","p":"Aumente todos os <code>precos</code> em 10% (sem <code>for</code>) e guarde em <code>reajustados</code>, arredondados para 2 casas com <code>np.round</code>.","s":"import numpy as np\nprecos = np.array([10.0, 25.5, 8.0, 40.0])","sol":"reajustados = np.round(precos * 1.1, 2)","test":"assert reajustados.tolist() == [11.0, 28.05, 8.8, 44.0], \"Multiplique o array por 1.1\"\nassert \"for \" not in codigo, \"Sem for: a operação é aplicada no array inteiro\"","h":["array * 1.1 multiplica todos os elementos","np.round(array, 2)"]},{"t":"Fatias","p":"De <code>vendas</code>, guarde em <code>primeiros</code> os 3 primeiros valores e em <code>ultimo</code> o último (índice negativo).","s":"import numpy as np\nvendas = np.array([120, 340, 90, 410, 275, 180])","sol":"primeiros = vendas[:3]\nultimo = vendas[-1]","test":"assert primeiros.tolist() == [120, 340, 90]\nassert ultimo == 180, \"Índice -1 é o último\"","h":["Fatia: vendas[:3]","Último: vendas[-1]"]},{"t":"Mais caro e mais barato","p":"Guarde em <code>maior</code> e <code>menor</code> o maior e o menor preço, e em <code>pos_maior</code> a <b>posição</b> do maior.","s":"import numpy as np\nprecos = np.array([35.9, 12.5, 89.0, 47.3])","sol":"maior = precos.max()\nmenor = precos.min()\npos_maior = precos.argmax()","test":"assert (maior, menor) == (89.0, 12.5)\nassert pos_maior == 2, \"argmax devolve a posição: 2\"","h":["max() e min()","argmax() devolve o índice do maior"]},{"t":"Total com dot","p":"Calcule o faturamento <code>total</code> multiplicando <code>unidades</code> por <code>precos</code> e somando, usando <code>np.dot</code>.","s":"import numpy as np\nunidades = np.array([3, 1, 5, 2])\nprecos = np.array([10.0, 25.5, 8.0, 40.0])","sol":"total = np.dot(unidades, precos)","test":"assert total == 175.5, \"3×10 + 1×25.5 + 5×8 + 2×40 = 175.5\"\nassert \"dot\" in codigo, \"Use np.dot\"","h":["np.dot(a, b) = soma dos produtos","É o mesmo que (a * b).sum()"]},{"t":"Filtro booleano","p":"Crie <code>acima</code> com os salários maiores que a média de <code>salarios</code> e <code>qtd_acima</code> com quantos são.","s":"import numpy as np\nsalarios = np.array([2500, 3800, 4200, 6000, 3100])","sol":"acima = salarios[salarios > salarios.mean()]\nqtd_acima = len(acima)","test":"assert acima.tolist() == [4200, 6000], \"Média = 3920: acima ficam 4200 e 6000\"\nassert qtd_acima == 2","h":["salarios > salarios.mean() gera True/False","Use isso entre colchetes para filtrar"]},{"t":"Faixa salarial","p":"Guarde em <code>faixa</code> os salários entre 3000 e 4500 (inclusive) usando <code>&amp;</code>.","s":"import numpy as np\nsalarios = np.array([2500, 3800, 4200, 6000, 3100, 4500])","sol":"faixa = salarios[(salarios >= 3000) & (salarios <= 4500)]","test":"assert faixa.tolist() == [3800, 4200, 3100, 4500]\nassert \"&\" in codigo, \"Combine as condições com &\"","h":["Cada condição entre parênteses","(cond1) & (cond2)"]},{"t":"np.where com dois retornos","p":"Crie <code>situacao</code> com <code>\"acima\"</code> para salários maiores que a média e <code>\"abaixo\"</code> para os demais, usando <code>np.where</code>.","s":"import numpy as np\nsalarios = np.array([2500, 3800, 4200, 6000])","sol":"situacao = np.where(salarios > salarios.mean(), \"acima\", \"abaixo\")","test":"assert situacao.tolist() == [\"abaixo\", \"abaixo\", \"acima\", \"acima\"], \"Média = 4125\"\nassert \"where\" in codigo","h":["np.where(condição, valor_se_verdadeiro, valor_se_falso)","A condição usa salarios.mean()"]},{"t":"Aleatórios com semente","p":"Crie <code>rng = np.random.default_rng(seed=42)</code> e gere <code>vendas</code> com 30 inteiros entre 100 e 500 (<code>rng.integers(100, 500, size=30)</code>). Depois guarde em <code>dia_top</code> o <b>dia</b> (posição + 1) com a maior venda.","s":"import numpy as np\n","sol":"rng = np.random.default_rng(seed=42)\nvendas = rng.integers(100, 500, size=30)\ndia_top = vendas.argmax() + 1","test":"_v = np.random.default_rng(seed=42).integers(100, 500, size=30)\nassert vendas.tolist() == _v.tolist(), \"Use default_rng(seed=42) e integers(100, 500, size=30)\"\nassert dia_top == _v.argmax() + 1, \"Dia = posição do maior + 1\"","h":["argmax() dá a posição (começa em 0)","Some 1 para virar \"dia\""]},{"t":"Medidas estatísticas","p":"Calcule a <code>media</code>, a <code>mediana</code> (percentil 50) e a <code>variancia</code> de <code>notas</code> com NumPy.","s":"import numpy as np\nnotas = np.array([6.0, 7.5, 8.0, 9.0, 4.5])","sol":"media = np.mean(notas)\nmediana = np.percentile(notas, 50)\nvariancia = np.var(notas)","test":"assert media == 7.0 and mediana == 7.5\nassert abs(variancia - 2.5) < 1e-9, \"np.var dá 2.5\"\nassert \"percentile\" in codigo, \"Use np.percentile(notas, 50) para a mediana\"","h":["np.mean, np.percentile(x, 50), np.var","O percentil 50 é a mediana"]},{"t":"Reshape em semanas","p":"<code>vendas</code> tem 14 dias. Reorganize em 2 linhas × 7 colunas em <code>semanas</code> e guarde em <code>total_semana</code> o total de cada semana (soma ao longo do eixo 1).","s":"import numpy as np\nvendas = np.array([10, 20, 15, 30, 25, 40, 35, 12, 18, 22, 28, 30, 45, 50])","sol":"semanas = vendas.reshape(2, 7)\ntotal_semana = semanas.sum(axis=1)","test":"assert semanas.shape == (2, 7), \"Use reshape(2, 7)\"\nassert total_semana.tolist() == [175, 205], \"Soma por linha: axis=1\"","h":["vendas.reshape(2, 7)","sum(axis=1) soma cada linha"]},{"t":"Total por dia da semana","p":"Com <code>semanas</code> (2×7), guarde em <code>por_dia</code> a soma de cada coluna (dia da semana) e em <code>melhor_dia</code> o nome do dia com maior soma, usando a lista <code>dias</code>.","s":"import numpy as np\nsemanas = np.array([[10, 20, 15, 30, 25, 40, 35], [12, 18, 22, 28, 30, 45, 50]])\ndias = ['seg', 'ter', 'qua', 'qui', 'sex', 'sab', 'dom']","sol":"por_dia = semanas.sum(axis=0)\nmelhor_dia = dias[por_dia.argmax()]","test":"assert por_dia.tolist() == [22, 38, 37, 58, 55, 85, 85], \"Soma por coluna: axis=0\"\nassert melhor_dia == \"sab\", \"Empate: argmax pega a primeira ocorrência (sab)\"","h":["axis=0 soma ao longo das linhas (resultado por coluna)","dias[posição]"]},{"t":"Ajuste salarial condicional","p":"Dê 10% de aumento só para quem ganha menos de 3000 e guarde o resultado em <code>novos</code> (use <code>np.where</code>; arredonde para 2 casas).","s":"import numpy as np\nsalarios = np.array([2500.0, 3800.0, 2900.0, 6000.0])","sol":"novos = np.round(np.where(salarios < 3000, salarios * 1.1, salarios), 2)","test":"assert novos.tolist() == [2750.0, 3800.0, 3190.0, 6000.0]\nassert salarios.tolist() == [2500.0, 3800.0, 2900.0, 6000.0], \"Não altere o array original\"","h":["np.where(condição, salarios * 1.1, salarios)","np.round(..., 2)"]},{"t":"Normalizar notas","p":"Converta <code>notas</code> para a escala 0–1 com a fórmula (x − mín) ÷ (máx − mín) e guarde em <code>normal</code>, com 3 casas.","s":"import numpy as np\nnotas = np.array([4.0, 6.0, 8.0, 10.0, 7.0])","sol":"normal = np.round((notas - notas.min()) / (notas.max() - notas.min()), 3)","test":"assert normal.tolist() == [0.0, 0.333, 0.667, 1.0, 0.5]","h":["Operações entre array e número valem para todos","(notas - notas.min()) / (notas.max() - notas.min())"]},{"t":"Desafio: matriz de vendas","p":"<code>vendas</code> tem 4 lojas (linhas) × 3 meses (colunas). Crie: <code>total_loja</code> (soma por loja), <code>media_mes</code> (média de cada mês, 1 casa), <code>loja_top</code> (índice da loja com maior total) e <code>meses_meta</code> (quantas células ≥ <code>meta</code>).","s":"import numpy as np\nvendas = np.array([[120, 150, 130], [90, 110, 95], [200, 180, 210], [60, 75, 80]])\nmeta = 120","sol":"total_loja = vendas.sum(axis=1)\nmedia_mes = np.round(vendas.mean(axis=0), 1)\nloja_top = int(total_loja.argmax())\nmeses_meta = int((vendas >= meta).sum())","test":"assert total_loja.tolist() == [400, 295, 590, 215]\nassert media_mes.tolist() == [117.5, 128.8, 128.8]\nassert loja_top == 2\nassert meses_meta == 6, \"6 células com venda >= 120\"\nassert rodar(meta=200)[\"meses_meta\"] == 2, \"Use a variável meta\"","h":["Por loja = linhas → axis=1; por mês = colunas → axis=0","(vendas >= meta).sum() conta os True"]}]},{"name":"Pandas","short":"análise de dados","cdesc":"biblioteca para análise de dados em tabelas","groups":[["Estruturas",[["Series","uma coluna com índice"],["DataFrame","tabela: linhas x colunas"]]],["Explorar e filtrar",[["Explorar","head(), info(), describe(), shape"],["Selecionar","df['col'], df[filtro], loc, iloc"]]],["Transformar",[["Limpar","dropna, fillna, astype, rename, drop_duplicates"],["Agregar","groupby, agg, merge, pivot_table, sort_values"]]]],"hot":["Instale com: pip install pandas  •  Importe sempre como: import pandas as pd","loc usa nomes (rótulos); iloc usa posições numéricas."],"trap":"Muitas operações retornam um NOVO DataFrame: atribua o resultado (df = df.dropna()).","examples":[["pandas_basico.py","import pandas as pd\n\ndados = {\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\"],\n    \"qtd\":     [10, 5, 30, 8],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5],\n}\ndf = pd.DataFrame(dados)\n\nprint(df.head())        # primeiras linhas\nprint(df.shape)         # (4, 4)\ndf.info()               # tipos e nulos\nprint(df.describe())    # estatísticas\n\n# Ler arquivos\n# df = pd.read_csv(\"vendas.csv\")\n# df = pd.read_excel(\"vendas.xlsx\")\n\n# Nova coluna calculada\ndf[\"total\"] = df[\"qtd\"] * df[\"preco\"]"],["pandas_selecao.py","# Selecionar colunas\nprint(df[\"produto\"])\nprint(df[[\"produto\", \"total\"]])\n\n# Filtrar linhas\nsp = df[df[\"cidade\"] == \"SP\"]\ngrandes = df[(df[\"qtd\"] > 5) & (df[\"preco\"] > 1)]\n\n# loc (rótulos) e iloc (posições)\nprint(df.loc[0, \"produto\"])     # Café\nprint(df.iloc[0:2, 0:2])\n\n# Ordenar\nprint(df.sort_values(\"total\", ascending=False))\n\n# Contagens\nprint(df[\"produto\"].value_counts())\nprint(df[\"cidade\"].unique())    # ['SP' 'RJ']"]],"ex":[{"t":"Criar DataFrame","p":"Crie <code>tabela</code>, um DataFrame com as colunas \"nome\" ([\"Ana\", \"Leo\"]) e \"idade\" ([25, 30]).","s":"","sol":"import pandas as pd\ntabela = pd.DataFrame({\"nome\": [\"Ana\", \"Leo\"], \"idade\": [25, 30]})","test":"assert tabela.shape == (2, 2) and list(tabela.columns) == [\"nome\", \"idade\"] and tabela[\"idade\"].tolist() == [25, 30]","h":["pd.DataFrame({coluna: lista})"]},{"t":"Coluna calculada","p":"Crie a coluna \"total\" = qtd × preco em <code>df</code>.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"df[\"total\"] = df[\"qtd\"] * df[\"preco\"]","test":"assert df[\"total\"].round(2).tolist() == [125.0, 29.5, 24.0, 100.0, 64.0]","h":["df[\"nova\"] = df[\"a\"] * df[\"b\"]"]},{"t":"Filtrar linhas","p":"Guarde em <code>sp</code> as linhas com cidade \"SP\".","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"sp = df[df[\"cidade\"] == \"SP\"]","test":"assert len(sp) == 3 and set(sp[\"cidade\"]) == {\"SP\"}","h":["df[df[\"col\"] == valor]"]},{"t":"Média de coluna","p":"Guarde a média de \"preco\" em <code>media</code> (round 2).","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"media = round(df[\"preco\"].mean(), 2)","test":"assert media == 12.74","h":[".mean()"]},{"t":"Ordenar","p":"Ordene df por \"qtd\" decrescente e guarde o produto da primeira linha em <code>top</code>.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"top = df.sort_values(\"qtd\", ascending=False).iloc[0][\"produto\"]","test":"assert top == \"Pão\"","h":["sort_values(..., ascending=False)",".iloc[0]"]},{"t":"groupby","p":"Some \"qtd\" por cidade em <code>por_cidade</code> (Series).","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"por_cidade = df.groupby(\"cidade\")[\"qtd\"].sum()","test":"assert por_cidade[\"SP\"] == 42 and por_cidade[\"RJ\"] == 13","h":["df.groupby(\"col\")[\"qtd\"].sum()"]},{"t":"value_counts","p":"Conte quantas vezes cada produto aparece em <code>contagem</code>.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"contagem = df[\"produto\"].value_counts()","test":"assert contagem[\"Café\"] == 2 and contagem[\"Pão\"] == 1","h":[".value_counts()"]},{"t":"fillna","p":"Preencha os nulos de \"idade\" em <code>d</code> com a média da coluna.","s":"import pandas as pd\nimport numpy as np\nd = pd.DataFrame({\"idade\": [20, np.nan, 40]})","sol":"d[\"idade\"] = d[\"idade\"].fillna(d[\"idade\"].mean())","test":"assert d[\"idade\"].isna().sum() == 0 and d[\"idade\"].tolist() == [20.0, 30.0, 40.0]","h":[".fillna(valor)"]},{"t":"dropna","p":"Remova de <code>d</code> as linhas sem \"nome\" e guarde em <code>limpo</code>.","s":"import pandas as pd\nd = pd.DataFrame({\"nome\": [\"Ana\", None, \"Bia\"], \"x\": [1, 2, 3]})","sol":"limpo = d.dropna(subset=[\"nome\"])","test":"assert limpo[\"nome\"].tolist() == [\"Ana\", \"Bia\"]","h":["dropna(subset=[...])"]},{"t":"Renomear coluna","p":"Renomeie a coluna \"qtd\" para \"quantidade\" em <code>df</code>.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"df = df.rename(columns={\"qtd\": \"quantidade\"})","test":"assert \"quantidade\" in df.columns and \"qtd\" not in df.columns","h":["rename(columns={antigo: novo})"]},{"t":"loc e iloc","p":"Guarde em <code>a</code> o produto da linha de índice 2 (use loc) e em <code>b</code> o preço da última linha (use iloc).","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"a = df.loc[2, \"produto\"]\nb = df.iloc[-1][\"preco\"]","test":"assert a == \"Pão\" and b == 32.0","h":["loc usa rótulos; iloc usa posições."]},{"t":"apply","p":"Crie a coluna \"faixa\": \"caro\" se preco &gt; 10, senão \"barato\".","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"df[\"faixa\"] = df[\"preco\"].apply(lambda p: \"caro\" if p > 10 else \"barato\")","test":"assert df[\"faixa\"].tolist() == [\"caro\", \"barato\", \"barato\", \"caro\", \"caro\"]","h":[".apply(lambda p: ...)"]},{"t":"merge","p":"Junte <code>df</code> com <code>estados</code> pela coluna \"cidade\" (left join) em <code>completo</code>.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})\nestados = pd.DataFrame({\"cidade\": [\"SP\", \"RJ\"], \"estado\": [\"São Paulo\", \"Rio de Janeiro\"]})","sol":"completo = df.merge(estados, on=\"cidade\", how=\"left\")","test":"assert len(completo) == 5 and \"estado\" in completo.columns and completo.loc[0, \"estado\"] == \"São Paulo\"","h":["df.merge(outro, on=..., how=\"left\")"]},{"t":"pivot_table","p":"Crie <code>tabela</code>: produto nas linhas, cidade nas colunas, soma de qtd, preenchendo vazios com 0.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"tabela = df.pivot_table(index=\"produto\", columns=\"cidade\", values=\"qtd\", aggfunc=\"sum\", fill_value=0)","test":"assert tabela.loc[\"Café\", \"SP\"] == 10 and tabela.loc[\"Café\", \"RJ\"] == 8 and tabela.loc[\"Pão\", \"RJ\"] == 0","h":["pivot_table(index=, columns=, values=, aggfunc=, fill_value=)"]},{"t":"Desafio: relatório","p":"Gere <code>relatorio</code>: por produto, a soma de qtd (\"qtd_total\") e a receita (qtd × preco, \"receita\"), ordenado pela receita decrescente.","s":"import pandas as pd\ndf = pd.DataFrame({\n    \"produto\": [\"Café\", \"Leite\", \"Pão\", \"Café\", \"Queijo\"],\n    \"cidade\":  [\"SP\", \"RJ\", \"SP\", \"RJ\", \"SP\"],\n    \"qtd\":     [10, 5, 30, 8, 2],\n    \"preco\":   [12.5, 5.9, 0.8, 12.5, 32.0],\n})","sol":"df[\"receita\"] = df[\"qtd\"] * df[\"preco\"]\nrelatorio = df.groupby(\"produto\").agg(qtd_total=(\"qtd\", \"sum\"), receita=(\"receita\", \"sum\")).sort_values(\"receita\", ascending=False)","test":"assert list(relatorio.index) == [\"Café\", \"Queijo\", \"Leite\", \"Pão\"]\nassert relatorio.loc[\"Café\", \"qtd_total\"] == 18 and round(relatorio.loc[\"Café\", \"receita\"], 2) == 225.0","h":["Crie a coluna receita antes.","groupby + agg(nome=(coluna, função))."]}],"map":"arvore","src":"Intermediário • Módulo 22","pkgs":["pandas"],"origem":"reaproveitada"},{"name":"Documentação, datas e APIs","short":"aprender qualquer biblioteca sozinho","cdesc":"ler documentação, datetime, conversão de datas no pandas, merge e respostas JSON de APIs","map":"fluxo","src":"Intermediário • Módulo 23","groups":[["Como ler documentação",[["Pesquisar","\"nome_da_biblioteca python\" no Google / PyPI"],["Getting Started","Quickstart / User Guide primeiro"],["Testar o exemplo","copie, rode e adapte aos seus dados"]]],["Dentro do Python",[["help(obj)","mostra a documentação"],["dir(obj)","lista métodos e atributos"],["obj.__doc__","a docstring em texto"]]],["datetime",[["from datetime import datetime","importa só a classe"],["datetime.strptime(txt, fmt)","texto → data"],["strftime(fmt) / timedelta","data → texto; somar/subtrair dias"]]],["Códigos de formato",[["%d %m %Y","dia, mês, ano com 4 dígitos"],["%H:%M:%S","hora, minuto, segundo"],["%A %B","nome do dia / do mês"]]],["Pandas na documentação",[["df.dtypes","tipo de cada coluna"],["pd.to_datetime(col, format=...)","converte texto em data"],["merge(left_on=, right_on=)","juntar tabelas com colunas de nomes diferentes"]]],["APIs",[["requests.get(url)","faz a requisição (precisa de internet)"],["Parâmetros na URL","?function=...&symbol=...&apikey=..."],["resposta.json()","vira dicionário/lista Python"]]]],"hot":["Comece pelo Getting Started/Quickstart; teste o exemplo antes de ler tudo.","strptime converte TEXTO em data; strftime converte DATA em texto.","Subtrair duas datas gera um timedelta; use .days para os dias.","Sem format, o pandas pode trocar dia e mês: informe format=\"%d/%m/%Y\".","Chaves de API são segredo: use variáveis de ambiente, nunca deixe no código."],"trap":"%m é mês e %M é minuto. Trocar os dois gera datas erradas sem nenhum erro aparente.","examples":[["datas.py","from datetime import datetime, timedelta\n\npagamento = datetime.strptime(\"15/03/2026\", \"%d/%m/%Y\")\nhoje = datetime(2026, 4, 2)\natraso = (hoje - pagamento).days          # 18\nvencimento = pagamento + timedelta(days=30)\nprint(vencimento.strftime(\"%d/%m/%Y\"))    # 14/04/2026"],["pandas_e_api.py","import pandas as pd, json\n\ntabela[\"Data Pagamento\"] = pd.to_datetime(tabela[\"Data Pagamento\"], format=\"%d/%m/%Y\")\ncompleta = tabela.merge(emails, left_on=\"Cliente\", right_on=\"Nome\")\n\n# no seu PC: resposta = requests.get(url).json()\nresposta = json.loads(texto_da_api)\nfor mes, dados in resposta[\"Monthly Adjusted Time Series\"].items():\n    print(mes, dados[\"4. close\"])"]],"ex":[{"t":"Ler a docstring","p":"Guarde em <code>doc</code> a documentação (docstring) da função <code>len</code>, usando o atributo <code>__doc__</code>.","s":"","sol":"doc = len.__doc__","test":"assert doc == len.__doc__ and \"number of items\" in doc, \"Use len.__doc__\"","h":["Toda função documentada tem __doc__","doc = len.__doc__"]},{"t":"Métodos disponíveis","p":"Usando <code>dir(str)</code>, crie a lista <code>metodos_is</code> com os métodos de texto que começam com <code>is</code> (ex.: <code>isdigit</code>).","s":"","sol":"metodos_is = [m for m in dir(str) if m.startswith(\"is\")]","test":"assert metodos_is == [m for m in dir(str) if m.startswith(\"is\")] and \"isdigit\" in metodos_is, \"Filtre dir(str) pelos que começam com is\"","h":["dir(str) lista nomes","startswith(\"is\")"]},{"t":"Criar uma data","p":"Importe com <code>from datetime import datetime</code> e crie <code>natal</code> com a data 25/12/2026.","s":"","sol":"from datetime import datetime\nnatal = datetime(2026, 12, 25)","test":"import datetime as _dt\nassert isinstance(natal, _dt.date) and (natal.year, natal.month, natal.day) == (2026, 12, 25), \"datetime(ano, mês, dia)\"","h":["datetime(ano, mês, dia)","A ordem é ano, mês, dia"]},{"t":"Texto para data","p":"Converta <code>texto</code> (formato dia/mês/ano) em data com <code>datetime.strptime</code> e guarde em <code>data</code>.","s":"from datetime import datetime\ntexto = \"15/03/2026\"","sol":"data = datetime.strptime(texto, \"%d/%m/%Y\")","test":"assert (data.year, data.month, data.day) == (2026, 3, 15), \"Formato: %d/%m/%Y\"\nd = rodar(texto=\"01/12/2025\")[\"data\"]\nassert (d.month, d.day) == (12, 1), \"Use a variável texto\"","h":["strptime = string parse time","\"%d/%m/%Y\""]},{"t":"Data para texto","p":"Formate <code>data</code> como <code>2026-03-15 às 09:05</code> com <code>strftime</code> e guarde em <code>texto</code>.","s":"from datetime import datetime\ndata = datetime(2026, 3, 15, 9, 5)","sol":"texto = data.strftime(\"%Y-%m-%d às %H:%M\")","test":"assert texto == \"2026-03-15 às 09:05\", \"Use %Y-%m-%d às %H:%M\"","h":["strftime = string format time","%H hora, %M minuto (M maiúsculo!)"]},{"t":"Dias em atraso","p":"Calcule <code>atraso</code> (em dias, inteiro) entre <code>pagamento</code> e <code>hoje</code>.","s":"from datetime import datetime\npagamento = datetime(2026, 3, 15)\nhoje = datetime(2026, 4, 2)","sol":"atraso = (hoje - pagamento).days","test":"assert atraso == 18, \"De 15/03 a 02/04 = 18 dias\"\nassert rodar(hoje=datetime(2026, 3, 20))[\"atraso\"] == 5, \"Use as variáveis\"","h":["Datas podem ser subtraídas","O resultado (timedelta) tem .days"]},{"t":"Vencimento com timedelta","p":"Crie <code>vencimentos</code>: lista de textos <code>dd/mm/aaaa</code> com 3 parcelas a cada 30 dias, começando 30 dias após <code>compra</code>.","s":"from datetime import datetime\ncompra = datetime(2026, 1, 10)","sol":"from datetime import timedelta\nvencimentos = [(compra + timedelta(days=30 * i)).strftime(\"%d/%m/%Y\") for i in range(1, 4)]","test":"assert vencimentos == [\"09/02/2026\", \"11/03/2026\", \"10/04/2026\"], \"30, 60 e 90 dias depois da compra\"","h":["from datetime import timedelta","compra + timedelta(days=30 * i)"]},{"t":"Tipos das colunas","p":"Guarde em <code>tipos</code> o resultado de <code>tabela.dtypes</code> e em <code>texto_data</code> se a coluna <code>Data Pagamento</code> está como texto (<code>True</code> se o dtype for <code>object</code>).","s":"import pandas as pd\ntabela = pd.DataFrame({\"Cliente\": [\"Ana\", \"Leo\"], \"Data Pagamento\": [\"15/03/2026\", \"02/04/2026\"]})","sol":"tipos = tabela.dtypes\ntexto_data = tabela[\"Data Pagamento\"].dtype == object","test":"assert list(tipos.index) == [\"Cliente\", \"Data Pagamento\"], \"Use tabela.dtypes\"\nassert texto_data == True, \"A coluna veio como texto (object)\"","h":["df.dtypes mostra o tipo de cada coluna","Compare tabela[\"Data Pagamento\"].dtype == object"]},{"t":"pd.to_datetime com format","p":"Converta a coluna <code>Data Pagamento</code> em data usando <code>pd.to_datetime</code> com <code>format=\"%d/%m/%Y\"</code> (a mesma coluna recebe o resultado).","s":"import pandas as pd\ntabela = pd.DataFrame({\"Cliente\": [\"Ana\", \"Leo\", \"Bia\"], \"Data Pagamento\": [\"05/03/2026\", \"12/01/2026\", \"01/02/2026\"]})","sol":"tabela[\"Data Pagamento\"] = pd.to_datetime(tabela[\"Data Pagamento\"], format=\"%d/%m/%Y\")","test":"assert str(tabela[\"Data Pagamento\"].dtype).startswith(\"datetime64\"), \"A coluna deve virar data\"\nassert tabela[\"Data Pagamento\"].dt.month.tolist() == [3, 1, 2], \"Dia/mês trocados? Use format=\\\"%d/%m/%Y\\\"\"","h":["pd.to_datetime(coluna, format=...)","Atribua de volta: tabela[\"col\"] = ..."]},{"t":"Merge com nomes diferentes","p":"Junte <code>tabela</code> (coluna <code>Cliente</code>) com <code>emails</code> (coluna <code>Nome</code>) em <code>completa</code>, usando <code>left_on</code> e <code>right_on</code>.","s":"import pandas as pd\ntabela = pd.DataFrame({\"Cliente\": [\"Ana\", \"Leo\", \"Bia\"], \"Valor\": [100, 250, 80]})\nemails = pd.DataFrame({\"Nome\": [\"Bia\", \"Ana\", \"Leo\"], \"Email\": [\"bia@x.com\", \"ana@x.com\", \"leo@x.com\"]})","sol":"completa = tabela.merge(emails, left_on=\"Cliente\", right_on=\"Nome\")","test":"assert len(completa) == 3 and \"Email\" in completa.columns, \"Use merge(..., left_on=\\\"Cliente\\\", right_on=\\\"Nome\\\")\"\nassert completa.set_index(\"Cliente\").loc[\"Leo\", \"Email\"] == \"leo@x.com\", \"Cada cliente com seu e-mail\"","h":["df.merge(outro, left_on=\"col_da_esquerda\", right_on=\"col_da_direita\")","A ordem das linhas segue a tabela da esquerda"]},{"t":"Ler a resposta de uma API","p":"<code>texto_api</code> tem a resposta (JSON) de uma API de cotações. Converta com <code>json.loads</code> e guarde em <code>fechamentos</code> o dicionário <code>{mês: fechamento (float)}</code> a partir de <code>\"Monthly Adjusted Time Series\"</code> e da chave <code>\"4. close\"</code>.","s":"texto_api = '{\"Meta Data\": {\"2. Symbol\": \"IBM\"}, \"Monthly Adjusted Time Series\": {\"2026-03-31\": {\"1. open\": \"180.1\", \"4. close\": \"185.2\"}, \"2026-02-28\": {\"1. open\": \"170.0\", \"4. close\": \"179.9\"}}}'","sol":"import json\ndados = json.loads(texto_api)\nfechamentos = {mes: float(v[\"4. close\"]) for mes, v in dados[\"Monthly Adjusted Time Series\"].items()}","test":"assert fechamentos == {\"2026-03-31\": 185.2, \"2026-02-28\": 179.9}, \"Percorra a série mensal e converta \\\"4. close\\\" para float\"","h":["json.loads(texto) devolve um dicionário","Percorra dados[\"Monthly Adjusted Time Series\"].items()"]},{"t":"Montar a URL da API","p":"Use <code>urllib.parse.urlencode</code> para montar <code>url</code> = <code>base</code> + <code>\"?\"</code> + parâmetros <code>function=TIME_SERIES_MONTHLY_ADJUSTED</code>, <code>symbol=simbolo</code> e <code>apikey=chave</code>. A chave vem de <code>os.environ[\"API_KEY\"]</code>.","s":"import os\nos.environ[\"API_KEY\"] = \"demo123\"\nbase = \"https://www.alphavantage.co/query\"\nsimbolo = \"IBM\"","sol":"from urllib.parse import urlencode\nchave = os.environ[\"API_KEY\"]\nparametros = {\"function\": \"TIME_SERIES_MONTHLY_ADJUSTED\", \"symbol\": simbolo, \"apikey\": chave}\nurl = base + \"?\" + urlencode(parametros)","test":"assert url == \"https://www.alphavantage.co/query?function=TIME_SERIES_MONTHLY_ADJUSTED&symbol=IBM&apikey=demo123\", \"Confira a ordem: function, symbol, apikey\"\nassert \"demo123\" not in codigo, \"Não escreva a chave no código: leia de os.environ\"\nassert rodar(simbolo=\"PETR4.SA\")[\"url\"].endswith(\"symbol=PETR4.SA&apikey=demo123\")","h":["urlencode(dicionario) gera a=1&b=2","chave = os.environ[\"API_KEY\"]"]},{"t":"Dia da semana","p":"Para cada data em <code>datas</code> (texto dd/mm/aaaa), descubra o dia da semana (0 = segunda … 6 = domingo, com <code>.weekday()</code>) e crie <code>uteis</code> só com as datas que caem de segunda a sexta (mantendo o texto).","s":"datas = [\"06/04/2026\", \"11/04/2026\", \"12/04/2026\", \"15/04/2026\"]","sol":"from datetime import datetime\nuteis = [d for d in datas if datetime.strptime(d, \"%d/%m/%Y\").weekday() < 5]","test":"assert uteis == [\"06/04/2026\", \"15/04/2026\"], \"11/04 é sábado e 12/04 é domingo\"","h":["weekday(): segunda = 0, sábado = 5, domingo = 6","Mantenha as datas com weekday() < 5"]},{"t":"Cobranças em atraso","p":"Em <code>tabela</code>, converta <code>Vencimento</code> para data (formato dd/mm/aaaa), crie a coluna <code>Dias Atraso</code> = (<code>hoje</code> − vencimento) em dias e guarde em <code>atrasados</code> só as linhas com atraso &gt; 0.","s":"import pandas as pd\nfrom datetime import datetime\nhoje = datetime(2026, 4, 10)\ntabela = pd.DataFrame({\"Cliente\": [\"Ana\", \"Leo\", \"Bia\"], \"Vencimento\": [\"01/04/2026\", \"20/04/2026\", \"05/03/2026\"]})","sol":"tabela[\"Vencimento\"] = pd.to_datetime(tabela[\"Vencimento\"], format=\"%d/%m/%Y\")\ntabela[\"Dias Atraso\"] = (hoje - tabela[\"Vencimento\"]).dt.days\natrasados = tabela[tabela[\"Dias Atraso\"] > 0]","test":"assert tabela[\"Dias Atraso\"].tolist() == [9, -10, 36], \"hoje - vencimento, em dias\"\nassert atrasados[\"Cliente\"].tolist() == [\"Ana\", \"Bia\"], \"Filtre Dias Atraso > 0\"","h":["Subtrair datas numa coluna gera timedelta: use .dt.days","Filtro: tabela[tabela[\"Dias Atraso\"] > 0]"]},{"t":"Desafio: resumo da API","p":"<code>texto_api</code> tem cotações diárias. Crie <code>resumo</code> com: <code>maior</code> (maior fechamento), <code>data_maior</code> (data do maior, em <code>dd/mm/aaaa</code>) e <code>variacao</code> (% do primeiro para o último dia em ordem de data, 2 casas).","s":"texto_api = '{\"Time Series (Daily)\": {\"2026-04-03\": {\"4. close\": \"112.0\"}, \"2026-04-01\": {\"4. close\": \"100.0\"}, \"2026-04-02\": {\"4. close\": \"118.5\"}}}'","sol":"import json\nfrom datetime import datetime\nserie = json.loads(texto_api)[\"Time Series (Daily)\"]\nprecos = {d: float(v[\"4. close\"]) for d, v in serie.items()}\ndatas = sorted(precos)\ndata_max = max(precos, key=precos.get)\nresumo = {\n    \"maior\": precos[data_max],\n    \"data_maior\": datetime.strptime(data_max, \"%Y-%m-%d\").strftime(\"%d/%m/%Y\"),\n    \"variacao\": round((precos[datas[-1]] / precos[datas[0]] - 1) * 100, 2),\n}","test":"assert resumo == {\"maior\": 118.5, \"data_maior\": \"02/04/2026\", \"variacao\": 12.0}, \"Ordene as datas (aaaa-mm-dd ordena como texto) antes da variação\"","h":["Datas no formato aaaa-mm-dd podem ser ordenadas com sorted()","max(dicionario, key=dicionario.get) devolve a chave do maior valor"]}]},{"name":"Gráficos (Matplotlib e Seaborn)","short":"dados que se explicam sozinhos","cdesc":"linha, barra, dispersão e histograma; títulos, eixos, cores, rótulos, legendas e Seaborn","map":"bolhas","src":"Intermediário • Módulo 24","pkgs":["matplotlib"],"groups":[["Estrutura",[["fig, ax = plt.subplots()","figura (tela) + eixo (gráfico)"],["plt.subplots(1, 2)","vários gráficos lado a lado"],["plt.show() / savefig","mostrar / salvar em arquivo"]]],["Tipos",[["plot","linha: evolução no tempo"],["bar / barh","barras: comparar categorias"],["scatter / hist","relação entre variáveis / distribuição"]]],["Personalizar",[["set_title, set_xlabel, set_ylabel","títulos e rótulos dos eixos"],["color, linestyle, marker","argumentos de palavra-chave"],["set_ylim / axis","limites dos eixos"]]],["Ler melhor",[["bar_label","valor em cima de cada barra"],["legend(label=...)","identifica as séries"],["grid / spines","linhas de grade; tirar bordas"]]],["Seaborn",[["import seaborn as sns","gráficos estatísticos prontos"],["sns.barplot(data=df, x=, y=)","trabalha direto com DataFrame"],["histplot, boxplot, heatmap","distribuição, outliers, correlação"]]]],"hot":["Prefira o estilo orientado a objeto: fig, ax = plt.subplots() e depois ax.metodo().","No plot(x, y) a ordem importa: primeiro o eixo X, depois o Y.","Barras comparam categorias; linha mostra evolução no tempo.","ax.bar_label(barras) coloca o valor em cima de cada barra.","Seaborn recebe o DataFrame inteiro: data=df, x=\"coluna\", y=\"coluna\"."],"trap":"Em plt.axis([xmin, xmax, ymin, ymax]) a ordem é fixa. Trocar faz o gráfico \"sumir\" da área visível.","examples":[["grafico_barras.py","import matplotlib.pyplot as plt\n\nmeses = [\"Jan\", \"Fev\", \"Mar\"]\nvendas = [120, 150, 90]\n\nfig, ax = plt.subplots(figsize=(6, 4))\nbarras = ax.bar(meses, vendas, color=\"#1E5AA8\")\nax.bar_label(barras)\nax.set_title(\"Vendas por mês\")\nax.set_ylabel(\"Unidades\")\nax.spines[[\"top\", \"right\"]].set_visible(False)\nplt.show()"],["seaborn.py","import seaborn as sns\nimport pandas as pd\n\ndf = pd.DataFrame({\"loja\": [\"A\", \"B\", \"A\", \"B\"], \"valor\": [10, 12, 14, 9]})\nax = sns.barplot(data=df, x=\"loja\", y=\"valor\", errorbar=None)\nax.set_title(\"Média por loja\")"]],"ex":[{"t":"Primeiro gráfico de linha","p":"Crie <code>fig, ax = plt.subplots()</code> e desenhe a linha de <code>vendas</code> por <code>meses</code> com <code>ax.plot</code>.<br><small class='muted'>O gráfico aparece abaixo do console quando você executa.</small>","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nax.plot(meses, vendas)","test":"assert len(ax.lines) == 1, \"Desenhe uma linha com ax.plot\"\nassert list(ax.lines[0].get_ydata()) == vendas, \"No eixo Y vão as vendas: plot(meses, vendas)\"","h":["fig, ax = plt.subplots()","ax.plot(eixo_x, eixo_y)"]},{"t":"Título e rótulos","p":"Faça um gráfico de linha de <code>vendas</code> por <code>meses</code> com o título <code>Vendas 2026</code>, eixo X <code>Mês</code> e eixo Y <code>Unidades</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nax.plot(meses, vendas)\nax.set_title(\"Vendas 2026\")\nax.set_xlabel(\"Mês\")\nax.set_ylabel(\"Unidades\")","test":"assert ax.get_title() == \"Vendas 2026\"\nassert (ax.get_xlabel(), ax.get_ylabel()) == (\"Mês\", \"Unidades\"), \"Use set_xlabel e set_ylabel\"","h":["ax.set_title(\"...\")","ax.set_xlabel / ax.set_ylabel"]},{"t":"Barras","p":"Faça um gráfico de <b>barras</b> de <code>vendas</code> por <code>meses</code> com a cor <code>#1E5AA8</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nax.bar(meses, vendas, color=\"#1E5AA8\")","test":"import matplotlib.colors as _mc\nassert len(ax.patches) == 6, \"Use ax.bar: uma barra por mês\"\nassert [p.get_height() for p in ax.patches] == vendas\nassert _mc.to_hex(ax.patches[0].get_facecolor()).lower() == \"#1e5aa8\", \"Use color=\\\"#1E5AA8\\\"\"","h":["ax.bar(x, y)","Cor por palavra-chave: color=\"#1E5AA8\""]},{"t":"Barras horizontais","p":"Faça um gráfico de barras <b>horizontais</b> (<code>barh</code>) de <code>vendas</code> por <code>produtos</code>.","s":"import matplotlib.pyplot as plt\nprodutos = ['Café', 'Pão', 'Leite']\nvendas = [320, 210, 180]","sol":"fig, ax = plt.subplots()\nax.barh(produtos, vendas)","test":"assert [round(p.get_width()) for p in ax.patches] == vendas, \"Em barh o comprimento é a largura (width)\"","h":["ax.barh(categorias, valores)","No barh as categorias ficam no eixo Y"]},{"t":"Salvar em arquivo","p":"Crie um gráfico de linha de <code>vendas</code> por <code>meses</code> e salve como <code>grafico.png</code> com <code>fig.savefig</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nax.plot(meses, vendas)\nfig.savefig(\"grafico.png\")","test":"import os\nassert os.path.exists(\"grafico.png\") and os.path.getsize(\"grafico.png\") > 1000, \"Use fig.savefig(\\\"grafico.png\\\")\"","h":["fig.savefig(\"nome.png\")","Salve depois de desenhar"]},{"t":"Valores nas barras","p":"Faça as barras de <code>vendas</code> por <code>meses</code> e coloque o valor em cima de cada barra com <code>ax.bar_label</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nbarras = ax.bar(meses, vendas)\nax.bar_label(barras)","test":"assert len(ax.patches) == 6, \"Desenhe as barras\"\nrotulos = [t.get_text() for t in ax.texts]\nassert rotulos == [str(v) for v in vendas], \"Use ax.bar_label(barras)\"","h":["Guarde o retorno: barras = ax.bar(...)","ax.bar_label(barras)"]},{"t":"Duas séries com legenda","p":"No mesmo eixo, desenhe <code>vendas_2025</code> e <code>vendas_2026</code> (por <code>meses</code>) com <code>label=\"2025\"</code> e <code>label=\"2026\"</code>, e mostre a legenda.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar']\nvendas_2025 = [100, 120, 90]\nvendas_2026 = [130, 125, 140]","sol":"fig, ax = plt.subplots()\nax.plot(meses, vendas_2025, label=\"2025\")\nax.plot(meses, vendas_2026, label=\"2026\")\nax.legend()","test":"assert len(ax.lines) == 2, \"Duas chamadas de ax.plot\"\nleg = ax.get_legend()\nassert leg is not None, \"Chame ax.legend()\"\nassert [t.get_text() for t in leg.get_texts()] == [\"2025\", \"2026\"], \"Use label=\\\"2025\\\" e label=\\\"2026\\\"\"","h":["Cada plot recebe label=\"...\"","ax.legend() mostra as legendas"]},{"t":"Limites do eixo","p":"Gráfico de linha de <code>vendas</code> por <code>meses</code> com o eixo Y começando em 0 e indo até o maior valor + 50.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, ax = plt.subplots()\nax.plot(meses, vendas)\nax.set_ylim(0, max(vendas) + 50)","test":"assert ax.get_ylim() == (0, 260), \"Y de 0 até max(vendas) + 50 = 260\"\nassert rodar(vendas=[1, 2, 3, 4, 5, 6])[\"ax\"].get_ylim() == (0, 56), \"Use max(vendas)\"","h":["ax.set_ylim(minimo, maximo)","max(vendas) + 50"]},{"t":"Dispersão","p":"Faça um gráfico de dispersão (<code>scatter</code>) de <code>preco</code> (X) por <code>vendidos</code> (Y), com pontos vermelhos (<code>color=\"red\"</code>).","s":"import matplotlib.pyplot as plt\npreco = [10, 15, 20, 25, 30]\nvendidos = [200, 170, 120, 90, 40]","sol":"fig, ax = plt.subplots()\nax.scatter(preco, vendidos, color=\"red\")","test":"import numpy as _np\npts = ax.collections[0].get_offsets()\nassert _np.array(pts).tolist() == [[10, 200], [15, 170], [20, 120], [25, 90], [30, 40]], \"scatter(preco, vendidos)\"\nassert tuple(ax.collections[0].get_facecolor()[0][:3]) == (1.0, 0.0, 0.0), \"Pontos vermelhos: color=\\\"red\\\"\"","h":["ax.scatter(x, y)","color=\"red\""]},{"t":"Histograma","p":"Faça o histograma de <code>idades</code> com 5 faixas (<code>bins=5</code>) e guarde as contagens em <code>contagens</code> (o 1º valor retornado por <code>ax.hist</code>).","s":"import matplotlib.pyplot as plt\nidades = [18, 22, 25, 25, 31, 33, 35, 41, 44, 52, 58, 60]","sol":"fig, ax = plt.subplots()\ncontagens, faixas, _ = ax.hist(idades, bins=5)","test":"assert list(contagens) == [4, 2, 2, 1, 3], \"Use bins=5\"\nassert len(ax.patches) == 5","h":["ax.hist(dados, bins=5)","Ele retorna (contagens, limites, barras)"]},{"t":"Dois gráficos lado a lado","p":"Crie <code>fig, (ax1, ax2) = plt.subplots(1, 2)</code>: em <code>ax1</code> barras de <code>vendas</code> e em <code>ax2</code> linha de <code>vendas</code>, ambos por <code>meses</code>. Título de <code>ax1</code>: <code>Barras</code>; de <code>ax2</code>: <code>Linha</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"fig, (ax1, ax2) = plt.subplots(1, 2)\nax1.bar(meses, vendas)\nax1.set_title(\"Barras\")\nax2.plot(meses, vendas)\nax2.set_title(\"Linha\")","test":"assert len(fig.axes) == 2, \"plt.subplots(1, 2)\"\nassert len(ax1.patches) == 6 and len(ax2.lines) == 1\nassert (ax1.get_title(), ax2.get_title()) == (\"Barras\", \"Linha\")","h":["subplots(1, 2) = 1 linha, 2 colunas","Cada eixo tem seus próprios métodos"]},{"t":"Destacar o maior","p":"Faça barras de <code>vendas</code> por <code>meses</code> em cinza (<code>#A39E93</code>), exceto a maior, que deve ficar azul (<code>#1E5AA8</code>). Monte a lista <code>cores</code> e passe em <code>color=cores</code>.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"cores = [\"#1E5AA8\" if v == max(vendas) else \"#A39E93\" for v in vendas]\nfig, ax = plt.subplots()\nax.bar(meses, vendas, color=cores)","test":"import matplotlib.colors as _mc\nc = [_mc.to_hex(p.get_facecolor()).upper() for p in ax.patches]\nassert c == [\"#A39E93\"] * 4 + [\"#1E5AA8\", \"#A39E93\"], \"Só a maior (Mai) em azul\"\nr = rodar(vendas=[9, 1, 1, 1, 1, 1])\nassert _mc.to_hex(r[\"ax\"].patches[0].get_facecolor()).upper() == \"#1E5AA8\", \"Calcule a partir de vendas\"","h":["Monte a lista de cores com if/else","color aceita uma lista, uma cor por barra"]},{"t":"Gráfico a partir do pandas","p":"Agrupe <code>df</code> por <code>loja</code>, some <code>valor</code> e faça barras com o resultado (lojas no X). Título: <code>Total por loja</code>.","s":"import matplotlib.pyplot as plt\nimport pandas as pd\ndf = pd.DataFrame({'loja': ['A', 'B', 'A', 'C', 'B'], 'valor': [100, 80, 50, 120, 40]})","sol":"total = df.groupby(\"loja\")[\"valor\"].sum()\nfig, ax = plt.subplots()\nax.bar(total.index, total.values)\nax.set_title(\"Total por loja\")","test":"assert [p.get_height() for p in ax.patches] == [150, 120, 120], \"A=150, B=120, C=120\"\nassert ax.get_title() == \"Total por loja\"","h":["df.groupby(\"loja\")[\"valor\"].sum()","ax.bar(total.index, total.values)"]},{"t":"Barras com Seaborn","p":"Com Seaborn, faça <code>ax = sns.barplot(data=df, x=\"loja\", y=\"valor\", errorbar=None, estimator=\"sum\")</code> e título <code>Vendas por loja</code>.<br><small class='muted'>Na 1ª vez o Seaborn é baixado (alguns segundos).</small>","s":"import matplotlib.pyplot as plt\nimport pandas as pd\nimport seaborn as sns\ndf = pd.DataFrame({'loja': ['A', 'B', 'A', 'C', 'B'], 'valor': [100, 80, 50, 120, 40]})","sol":"ax = sns.barplot(data=df, x=\"loja\", y=\"valor\", errorbar=None, estimator=\"sum\")\nax.set_title(\"Vendas por loja\")","test":"assert [round(p.get_height()) for p in ax.patches] == [150, 120, 120], \"Some por loja com estimator=\\\"sum\\\"\"\nassert ax.get_title() == \"Vendas por loja\"","h":["sns.barplot(data=df, x=..., y=...)","estimator=\"sum\" soma em vez de tirar a média"]},{"t":"Desafio: painel de vendas","p":"Crie <code>fig, axs = plt.subplots(2, 1)</code>. Em <code>axs[0]</code>: linha de <code>vendas</code> por <code>meses</code> com marcadores <code>\"o\"</code> e a média como linha horizontal tracejada (<code>axhline</code>, <code>linestyle=\"--\"</code>). Em <code>axs[1]</code>: barras do crescimento mês a mês (<code>vendas[i] - vendas[i-1]</code>, a partir de Fev), verde se ≥ 0 e vermelho se &lt; 0.","s":"import matplotlib.pyplot as plt\nmeses = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun']\nvendas = [120, 150, 90, 180, 210, 160]\n","sol":"media = sum(vendas) / len(vendas)\ncresc = [vendas[i] - vendas[i - 1] for i in range(1, len(vendas))]\nfig, axs = plt.subplots(2, 1)\naxs[0].plot(meses, vendas, marker=\"o\")\naxs[0].axhline(media, linestyle=\"--\")\naxs[1].bar(meses[1:], cresc, color=[\"green\" if c >= 0 else \"red\" for c in cresc])","test":"import matplotlib.colors as _mc\nl = axs[0].lines\nassert len(l) == 2, \"Uma linha de vendas + a linha da média\"\nassert l[0].get_marker() == \"o\", \"marker=\\\"o\\\"\"\nassert l[1].get_linestyle() == \"--\" and list(l[1].get_ydata()) == [sum(vendas) / len(vendas)] * 2, \"axhline(media, linestyle=\\\"--\\\")\"\nassert [p.get_height() for p in axs[1].patches] == [30, -60, 90, 30, -50], \"Crescimento a partir de Fev\"\nassert [_mc.to_hex(p.get_facecolor()) for p in axs[1].patches] == [\"#008000\", \"#ff0000\", \"#008000\", \"#008000\", \"#ff0000\"], \"Verde se >= 0, vermelho se < 0\"","h":["axs[0].axhline(valor, linestyle=\"--\")","Lista de cores com list comprehension"]}]},{"name":"Arquivos de texto (e PDF)","short":"ler e gravar dados em arquivos","cdesc":"open, modos r/w/a, with, linhas, encoding, CSV e noções de PDF","map":"arvore","src":"Intermediário • Módulo 25","groups":[["Abrir",[["open(caminho, modo)","r ler, w gravar (apaga), a acrescentar"],["encoding=\"utf-8\"","evita problema com acentos"],["with open(...) as f:","fecha o arquivo sozinho"]]],["Ler",[["f.read()","tudo num texto só"],["f.readlines()","lista de linhas (com \\n)"],["for linha in f:","linha a linha, economiza memória"]]],["Gravar",[["f.write(texto)","não põe \\n sozinho"],["modo \"a\"","acrescenta no fim"],["f.writelines(lista)","várias linhas de uma vez"]]],["Tratar o texto",[["strip()","tira \\n e espaços das pontas"],["split(\";\")","separa as colunas"],["csv.reader / DictReader","lê CSV respeitando aspas"]]],["PDF (no seu PC)",[["pypdf / PyPDF2","PdfReader, PdfWriter, juntar e separar páginas"],["extract_text()","pegar texto de uma página"],["tabula","ler tabelas de PDF para o pandas"]]]],"hot":["Use sempre with open(...): o arquivo é fechado mesmo se der erro.","Modo \"w\" APAGA o conteúdo anterior; para acrescentar use \"a\".","write não pula linha: escreva \"\\n\" no final.","Cada linha lida termina com \\n; use strip() antes de comparar ou converter.","Informe encoding=\"utf-8\" para não estragar acentos."],"trap":"Abrir com \"w\" para \"adicionar uma linha\" apaga o arquivo inteiro. Para adicionar, use \"a\".","examples":[["arquivos.py","with open(\"clientes.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Ana\\n\")\n    f.write(\"Leo\\n\")\n\nwith open(\"clientes.txt\", \"a\", encoding=\"utf-8\") as f:\n    f.write(\"Bia\\n\")\n\nwith open(\"clientes.txt\", encoding=\"utf-8\") as f:\n    nomes = [linha.strip() for linha in f]\nprint(nomes)   # ['Ana', 'Leo', 'Bia']"],["pdf_no_seu_pc.py","# Não roda no navegador: execute no seu computador (pip install pypdf)\nfrom pypdf import PdfReader, PdfWriter\n\nleitor = PdfReader(\"relatorio.pdf\")\nprint(leitor.pages[0].extract_text())\n\nescritor = PdfWriter()\nfor pagina in leitor.pages[:2]:\n    escritor.add_page(pagina)\nescritor.write(\"duas_paginas.pdf\")"]],"ex":[{"t":"Ler um arquivo","p":"O arquivo <code>mensagem.txt</code> já existe na pasta. Leia todo o conteúdo e guarde em <code>conteudo</code>.","s":"with open(\"mensagem.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Olá, Python!\\nArquivos são fáceis.\")","sol":"with open(\"mensagem.txt\", encoding=\"utf-8\") as f:\n    conteudo = f.read()","test":"assert conteudo == \"Olá, Python!\\nArquivos são fáceis.\", \"Use f.read()\"","h":["with open(\"mensagem.txt\", encoding=\"utf-8\") as f:","conteudo = f.read()"]},{"t":"Gravar um arquivo","p":"Crie o arquivo <code>saida.txt</code> com o texto de <code>texto</code>.","s":"texto = \"Relatório gerado pelo Python\"","sol":"with open(\"saida.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(texto)","test":"assert open(\"saida.txt\", encoding=\"utf-8\").read() == texto, \"O arquivo deve conter exatamente o texto\"","h":["Modo \"w\" cria/regrava o arquivo","f.write(texto)"]},{"t":"Uma linha por item","p":"Grave cada nome de <code>nomes</code> em uma linha do arquivo <code>nomes.txt</code>.","s":"nomes = [\"Ana\", \"Leo\", \"Bia\"]","sol":"with open(\"nomes.txt\", \"w\", encoding=\"utf-8\") as f:\n    for nome in nomes:\n        f.write(nome + \"\\n\")","test":"assert open(\"nomes.txt\", encoding=\"utf-8\").read().splitlines() == [\"Ana\", \"Leo\", \"Bia\"], \"Uma linha por nome\"","h":["write não pula linha sozinho","f.write(nome + \"\\n\")"]},{"t":"Acrescentar sem apagar","p":"O arquivo <code>log.txt</code> já tem 2 linhas. Acrescente a linha <code>evento</code> no final <b>sem apagar</b> o que existe.","s":"with open(\"log.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"inicio\\nprocessando\\n\")\nevento = \"fim\"","sol":"with open(\"log.txt\", \"a\", encoding=\"utf-8\") as f:\n    f.write(evento + \"\\n\")","test":"assert open(\"log.txt\", encoding=\"utf-8\").read().splitlines() == [\"inicio\", \"processando\", \"fim\"], \"Use o modo \\\"a\\\" (append)\"","h":["Modo \"a\" = append","Não esqueça o \\n"]},{"t":"Linhas sem o \\n","p":"Leia <code>produtos.txt</code> e guarde em <code>produtos</code> a lista de linhas <b>sem</b> o <code>\\n</code> e sem linhas vazias.","s":"with open(\"produtos.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Café\\nPão\\n\\nLeite\\n\")","sol":"with open(\"produtos.txt\", encoding=\"utf-8\") as f:\n    produtos = [linha.strip() for linha in f if linha.strip()]","test":"assert produtos == [\"Café\", \"Pão\", \"Leite\"], \"Use strip() e ignore linhas vazias\"","h":["for linha in f percorre linha a linha","linha.strip() remove o \\n"]},{"t":"Somar valores do arquivo","p":"<code>vendas.txt</code> tem um valor por linha. Calcule <code>total</code> (float).","s":"with open(\"vendas.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"150.50\\n200\\n99.50\\n\")","sol":"total = 0\nwith open(\"vendas.txt\", encoding=\"utf-8\") as f:\n    for linha in f:\n        total += float(linha)","test":"assert total == 450.0, \"150.50 + 200 + 99.50 = 450\"","h":["Cada linha é texto: converta com float()","float(\"200\\n\") funciona, o \\n é ignorado"]},{"t":"Separar colunas","p":"<code>clientes.txt</code> tem linhas <code>nome;cidade</code>. Crie o dicionário <code>cidade_de</code> <code>{nome: cidade}</code>.","s":"with open(\"clientes.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Ana;Recife\\nLeo;Olinda\\nBia;Caruaru\\n\")","sol":"cidade_de = {}\nwith open(\"clientes.txt\", encoding=\"utf-8\") as f:\n    for linha in f:\n        nome, cidade = linha.strip().split(\";\")\n        cidade_de[nome] = cidade","test":"assert cidade_de == {\"Ana\": \"Recife\", \"Leo\": \"Olinda\", \"Bia\": \"Caruaru\"}, \"Faça strip() antes do split(\\\";\\\")\"","h":["linha.strip().split(\";\")","Desempacote: nome, cidade = ..."]},{"t":"Contar palavras","p":"Leia <code>texto.txt</code> e guarde em <code>qtd_palavras</code> o número de palavras e em <code>qtd_linhas</code> o número de linhas.","s":"with open(\"texto.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Python é uma linguagem\\nmuito usada em dados\\ne automação\\n\")","sol":"with open(\"texto.txt\", encoding=\"utf-8\") as f:\n    linhas = f.readlines()\nqtd_linhas = len(linhas)\nqtd_palavras = sum(len(l.split()) for l in linhas)","test":"assert qtd_linhas == 3, \"3 linhas\"\nassert qtd_palavras == 10, \"4 + 4 + 2 = 10 palavras\"","h":["readlines() devolve a lista de linhas","split() sem argumentos separa por espaços"]},{"t":"Ler CSV com csv.DictReader","p":"Leia <code>notas.csv</code> com <code>csv.DictReader</code> e crie <code>aprovados</code>: lista de nomes com nota ≥ 7.","s":"with open(\"notas.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n    f.write(\"nome,nota\\nAna,8.5\\nLeo,6.0\\nBia,7.0\\n\")","sol":"import csv\nwith open(\"notas.csv\", encoding=\"utf-8\", newline=\"\") as f:\n    aprovados = [l[\"nome\"] for l in csv.DictReader(f) if float(l[\"nota\"]) >= 7]","test":"assert aprovados == [\"Ana\", \"Bia\"], \"Converta a nota com float()\"\nassert \"DictReader\" in codigo","h":["Cada linha do DictReader é um dicionário","linha[\"nota\"] é texto: use float()"]},{"t":"Gravar CSV","p":"Grave <code>vendas</code> (lista de tuplas) em <code>vendas.csv</code> com cabeçalho <code>produto,quantidade</code>, usando <code>csv.writer</code>.","s":"vendas = [(\"Café\", 30), (\"Pão\", 45)]","sol":"import csv\nwith open(\"vendas.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n    escritor = csv.writer(f)\n    escritor.writerow([\"produto\", \"quantidade\"])\n    escritor.writerows(vendas)","test":"assert open(\"vendas.csv\", encoding=\"utf-8\").read().splitlines() == [\"produto,quantidade\", \"Café,30\", \"Pão,45\"]","h":["csv.writer(f).writerow([...])","writerows(lista) grava várias linhas"]},{"t":"Copiar filtrando","p":"Copie para <code>erros.txt</code> apenas as linhas de <code>sistema.log</code> que contêm <code>ERRO</code>.","s":"with open(\"sistema.log\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"INFO inicio\\nERRO disco cheio\\nINFO ok\\nERRO timeout\\n\")","sol":"with open(\"sistema.log\", encoding=\"utf-8\") as origem, open(\"erros.txt\", \"w\", encoding=\"utf-8\") as destino:\n    for linha in origem:\n        if \"ERRO\" in linha:\n            destino.write(linha)","test":"assert open(\"erros.txt\", encoding=\"utf-8\").read().splitlines() == [\"ERRO disco cheio\", \"ERRO timeout\"]","h":["Dá para abrir dois arquivos no mesmo with","if \"ERRO\" in linha: destino.write(linha)"]},{"t":"Arquivo inexistente","p":"Crie <code>ler_seguro(caminho)</code> que retorna o conteúdo do arquivo ou a string <code>\"arquivo não encontrado\"</code> se ele não existir.","s":"with open(\"existe.txt\", \"w\") as f:\n    f.write(\"ok\")","sol":"def ler_seguro(caminho):\n    try:\n        with open(caminho, encoding=\"utf-8\") as f:\n            return f.read()\n    except FileNotFoundError:\n        return \"arquivo não encontrado\"","test":"assert ler_seguro(\"existe.txt\") == \"ok\"\nassert ler_seguro(\"nao_existe.txt\") == \"arquivo não encontrado\", \"Trate FileNotFoundError\"","h":["Arquivo inexistente gera FileNotFoundError","try / except FileNotFoundError"]},{"t":"Relatório em arquivo","p":"Gere <code>relatorio.txt</code> com uma linha por vendedor no formato <code>Ana: R$ 1,500.00</code> (ordem do dicionário) e, na última linha, <code>Total: R$ 2,750.50</code>.","s":"vendas = {\"Ana\": 1500, \"Leo\": 1250.5}","sol":"with open(\"relatorio.txt\", \"w\", encoding=\"utf-8\") as f:\n    for nome, valor in vendas.items():\n        f.write(f\"{nome}: R$ {valor:,.2f}\\n\")\n    f.write(f\"Total: R$ {sum(vendas.values()):,.2f}\\n\")","test":"assert open(\"relatorio.txt\", encoding=\"utf-8\").read().splitlines() == [\"Ana: R$ 1,500.00\", \"Leo: R$ 1,250.50\", \"Total: R$ 2,750.50\"]","h":["f-string com :,.2f","sum(vendas.values()) para o total"]},{"t":"Atualizar estoque","p":"<code>estoque.txt</code> tem linhas <code>produto;quantidade</code>. Subtraia as quantidades de <code>vendidos</code> (dict) e <b>regrave</b> o arquivo no mesmo formato e ordem.","s":"with open(\"estoque.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Café;50\\nPão;30\\nLeite;20\\n\")\nvendidos = {\"Café\": 5, \"Leite\": 20}","sol":"with open(\"estoque.txt\", encoding=\"utf-8\") as f:\n    linhas = [l.strip().split(\";\") for l in f if l.strip()]\nwith open(\"estoque.txt\", \"w\", encoding=\"utf-8\") as f:\n    for produto, qtd in linhas:\n        f.write(f\"{produto};{int(qtd) - vendidos.get(produto, 0)}\\n\")","test":"assert open(\"estoque.txt\", encoding=\"utf-8\").read().splitlines() == [\"Café;45\", \"Pão;30\", \"Leite;0\"], \"Leia tudo primeiro, depois regrave\"","h":["Leia o arquivo inteiro antes de abrir com \"w\"","vendidos.get(produto, 0) para quem não vendeu"]},{"t":"Desafio: consolidar arquivos","p":"Os arquivos <code>loja_a.txt</code>, <code>loja_b.txt</code> e <code>loja_c.txt</code> têm linhas <code>produto;valor</code>. Crie <code>consolidado.csv</code> com cabeçalho <code>produto,total</code> e o total de cada produto somando as três lojas, em ordem alfabética, com 2 casas decimais.","s":"dados = {\"loja_a.txt\": \"Café;10.5\\nPão;3\\n\", \"loja_b.txt\": \"Pão;2.5\\nLeite;7\\n\", \"loja_c.txt\": \"Café;4.5\\nLeite;1\\n\"}\nfor nome, conteudo in dados.items():\n    with open(nome, \"w\", encoding=\"utf-8\") as f:\n        f.write(conteudo)","sol":"totais = {}\nfor nome in [\"loja_a.txt\", \"loja_b.txt\", \"loja_c.txt\"]:\n    with open(nome, encoding=\"utf-8\") as f:\n        for linha in f:\n            produto, valor = linha.strip().split(\";\")\n            totais[produto] = totais.get(produto, 0) + float(valor)\nwith open(\"consolidado.csv\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"produto,total\\n\")\n    for produto in sorted(totais):\n        f.write(f\"{produto},{totais[produto]:.2f}\\n\")","test":"assert open(\"consolidado.csv\", encoding=\"utf-8\").read().splitlines() == [\"produto,total\", \"Café,15.00\", \"Leite,8.00\", \"Pão,5.50\"]","h":["Acumule num dicionário com get(produto, 0)","sorted(dicionario) ordena as chaves"]}]},{"name":"Arquivos e pastas do computador","short":"automatizar a organização de arquivos","cdesc":"os, os.path, pathlib e shutil: listar, criar, renomear, mover e copiar","map":"arvore","src":"Intermediário • Módulo 26","groups":[["Onde estou?",[["os.getcwd()","pasta atual do programa"],["Caminho relativo","\"relatorios/r1.pdf\" a partir da pasta atual"],["os.path.join(a, b)","monta caminhos sem errar a barra"]]],["Listar",[["os.listdir(pasta)","nomes de arquivos e pastas"],["os.path.isfile / isdir","é arquivo? é pasta?"],["Path(pasta).glob(\"*.pdf\")","filtra por padrão"]]],["Criar e verificar",[["os.makedirs(p, exist_ok=True)","cria pastas (e subpastas)"],["os.path.exists(p)","já existe?"],["os.path.splitext(nome)","separa nome e extensão"]]],["Mover e copiar (shutil)",[["shutil.copy(origem, destino)","copia arquivo"],["shutil.move(origem, destino)","move ou renomeia"],["os.rename / os.remove","renomear / apagar"]]],["pathlib (moderno)",[["Path(\"a\") / \"b.txt\"","monta caminho com /"],["p.suffix, p.stem, p.name","extensão, nome sem extensão, nome"],["p.read_text() / write_text()","ler e gravar rápido"]]]],"hot":["Use os.path.join ou Path para montar caminhos: funciona no Windows e no Linux.","os.listdir devolve só os NOMES; junte com a pasta para ter o caminho completo.","makedirs(..., exist_ok=True) não dá erro se a pasta já existir.","shutil.move serve tanto para mover quanto para renomear.","Teste a automação numa cópia da pasta antes de rodar nos arquivos reais."],"trap":"os.remove e shutil.move não pedem confirmação nem mandam para a lixeira. Imprima o que vai fazer antes de executar de verdade.","examples":[["organizar.py","import os, shutil\n\nfor nome in os.listdir(\".\"):\n    if os.path.isfile(nome):\n        extensao = os.path.splitext(nome)[1].lower().strip(\".\") or \"sem_extensao\"\n        os.makedirs(extensao, exist_ok=True)\n        shutil.move(nome, os.path.join(extensao, nome))"],["pathlib.py","from pathlib import Path\n\npasta = Path(\"relatorios\")\nfor arquivo in pasta.glob(\"*.pdf\"):\n    print(arquivo.name, arquivo.stem, arquivo.suffix)\n\n(Path(\"saida\") / \"resumo.txt\").parent.mkdir(exist_ok=True)\n(Path(\"saida\") / \"resumo.txt\").write_text(\"ok\", encoding=\"utf-8\")"]],"ex":[{"t":"Listar a pasta","p":"Guarde em <code>itens</code> a lista <b>ordenada</b> com os nomes do que existe na pasta atual (<code>os.listdir(\".\")</code>).","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\nitens = sorted(os.listdir(\".\"))","test":"assert itens == [\"foto1.jpg\", \"fotos\", \"nota.txt\", \"relatorios\", \"vendas_fev.xlsx\", \"vendas_jan.xlsx\"]","h":["import os","sorted(os.listdir(\".\"))"]},{"t":"Só arquivos","p":"Crie <code>arquivos</code> com os nomes (ordenados) que são <b>arquivos</b> na pasta atual, ignorando as pastas.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\narquivos = sorted(n for n in os.listdir(\".\") if os.path.isfile(n))","test":"assert arquivos == [\"foto1.jpg\", \"nota.txt\", \"vendas_fev.xlsx\", \"vendas_jan.xlsx\"], \"Use os.path.isfile\"","h":["os.path.isfile(nome)","Filtre a lista do listdir"]},{"t":"Montar caminho","p":"Use <code>os.path.join</code> para montar o caminho da pasta <code>relatorios</code> com o arquivo <code>r1.pdf</code> em <code>caminho</code>, e guarde em <code>existe</code> se ele existe.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\ncaminho = os.path.join(\"relatorios\", \"r1.pdf\")\nexiste = os.path.exists(caminho)","test":"import os as _o\nassert caminho == _o.path.join(\"relatorios\", \"r1.pdf\"), \"Use os.path.join\"\nassert existe is True","h":["os.path.join(\"pasta\", \"arquivo\")","os.path.exists(caminho)"]},{"t":"Criar pasta","p":"Crie a pasta <code>backup/2026</code> (com a subpasta) sem dar erro se já existir.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\nos.makedirs(os.path.join(\"backup\", \"2026\"), exist_ok=True)","test":"import os as _o\nassert _o.path.isdir(_o.path.join(\"backup\", \"2026\")), \"Use os.makedirs(..., exist_ok=True)\"","h":["os.makedirs cria as pastas intermediárias","exist_ok=True evita erro"]},{"t":"Separar a extensão","p":"Para cada nome em <code>nomes</code>, guarde a extensão (sem o ponto, minúscula) na lista <code>extensoes</code>, usando <code>os.path.splitext</code>.","s":"nomes = [\"Planilha.XLSX\", \"foto.jpg\", \"contrato.final.pdf\"]","sol":"import os\nextensoes = [os.path.splitext(n)[1].lower().lstrip(\".\") for n in nomes]","test":"assert extensoes == [\"xlsx\", \"jpg\", \"pdf\"], \"splitext(\\\"a.b.pdf\\\") devolve (\\\"a.b\\\", \\\".pdf\\\")\"","h":["os.path.splitext(nome) devolve (nome, \".ext\")","lower() e lstrip(\".\")"]},{"t":"Copiar arquivo","p":"Copie <code>nota.txt</code> para a pasta <code>relatorios</code> com <code>shutil.copy</code>, mantendo o original.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import shutil\nshutil.copy(\"nota.txt\", \"relatorios\")","test":"import os as _o\nassert _o.path.exists(_o.path.join(\"relatorios\", \"nota.txt\")), \"A cópia deve estar em relatorios\"\nassert _o.path.exists(\"nota.txt\"), \"O original deve continuar na pasta\"","h":["import shutil","shutil.copy(origem, pasta_destino)"]},{"t":"Mover por extensão","p":"Mova todos os arquivos <code>.jpg</code> da pasta atual para a pasta <code>fotos</code>.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os, shutil\nfor nome in os.listdir(\".\"):\n    if os.path.isfile(nome) and nome.endswith(\".jpg\"):\n        shutil.move(nome, os.path.join(\"fotos\", nome))","test":"import os as _o\nassert sorted(_o.listdir(\"fotos\")) == [\"foto1.jpg\", \"praia.jpg\"]\nassert not _o.path.exists(\"foto1.jpg\"), \"Mova (não copie)\"","h":["nome.endswith(\".jpg\")","shutil.move(origem, destino)"]},{"t":"Renomear em lote","p":"Renomeie os arquivos que começam com <code>vendas_</code> trocando o prefixo por <code>2026_vendas_</code> (ex.: <code>vendas_jan.xlsx</code> → <code>2026_vendas_jan.xlsx</code>).","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\nfor nome in os.listdir(\".\"):\n    if nome.startswith(\"vendas_\"):\n        os.rename(nome, \"2026_\" + nome)","test":"import os as _o\nassert sorted(n for n in _o.listdir(\".\") if \"vendas\" in n) == [\"2026_vendas_fev.xlsx\", \"2026_vendas_jan.xlsx\"]","h":["os.rename(nome_antigo, nome_novo)","\"2026_\" + nome"]},{"t":"Glob com pathlib","p":"Use <code>Path(\"relatorios\").glob(\"*.pdf\")</code> para criar <code>pdfs</code>: lista ordenada só com os <b>nomes sem extensão</b> (<code>.stem</code>).","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"from pathlib import Path\npdfs = sorted(p.stem for p in Path(\"relatorios\").glob(\"*.pdf\"))","test":"assert pdfs == [\"r1\", \"r2\"]\nassert \"glob\" in codigo","h":["from pathlib import Path",".stem é o nome sem extensão"]},{"t":"Tamanho dos arquivos","p":"Crie <code>tamanhos</code>: dicionário <code>{nome: tamanho em bytes}</code> dos arquivos da pasta atual (ignore pastas), com <code>os.path.getsize</code>.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\ntamanhos = {n: os.path.getsize(n) for n in os.listdir(\".\") if os.path.isfile(n)}","test":"assert tamanhos == {\"vendas_jan.xlsx\": 1, \"vendas_fev.xlsx\": 1, \"nota.txt\": 7, \"foto1.jpg\": 3}","h":["os.path.getsize(caminho)","Dict comprehension com filtro isfile"]},{"t":"Percorrer subpastas","p":"Use <code>os.walk(\".\")</code> para contar quantos arquivos existem no total (pasta atual + subpastas) em <code>total</code>.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\ntotal = 0\nfor raiz, pastas, arquivos in os.walk(\".\"):\n    total += len(arquivos)","test":"assert total == 7, \"4 na raiz + 2 em relatorios + 1 em fotos\"\nassert \"walk\" in codigo","h":["os.walk devolve (pasta, subpastas, arquivos) para cada pasta","Some len(arquivos)"]},{"t":"Ler e gravar com Path","p":"Com <code>pathlib</code>, leia <code>nota.txt</code>, converta para maiúsculas e grave em <code>saida/NOTA.txt</code> (crie a pasta <code>saida</code>).","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"from pathlib import Path\ntexto = Path(\"nota.txt\").read_text()\ndestino = Path(\"saida\") / \"NOTA.txt\"\ndestino.parent.mkdir(exist_ok=True)\ndestino.write_text(texto.upper())","test":"from pathlib import Path as _P\nassert (_P(\"saida\") / \"NOTA.txt\").read_text() == \"LEMBRAR\"","h":["Path(\"a\") / \"b\" monta caminhos","read_text(), write_text() e parent.mkdir()"]},{"t":"Organizar por extensão","p":"Mova cada arquivo da pasta atual para uma pasta com o nome da sua extensão (<code>xlsx</code>, <code>txt</code>, <code>jpg</code>...). Pastas existentes não devem ser mexidas.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os, shutil\nfor nome in os.listdir(\".\"):\n    if os.path.isfile(nome):\n        ext = os.path.splitext(nome)[1].lstrip(\".\").lower()\n        os.makedirs(ext, exist_ok=True)\n        shutil.move(nome, os.path.join(ext, nome))","test":"import os as _o\nassert sorted(_o.listdir(\"xlsx\")) == [\"vendas_fev.xlsx\", \"vendas_jan.xlsx\"]\nassert _o.listdir(\"txt\") == [\"nota.txt\"] and _o.listdir(\"jpg\") == [\"foto1.jpg\"]\nassert sorted(_o.listdir(\"relatorios\")) == [\"r1.pdf\", \"r2.pdf\"], \"Não mexa nas pastas que já existiam\"\nassert not [n for n in _o.listdir(\".\") if _o.path.isfile(n)], \"Não deve sobrar arquivo solto\"","h":["Pegue a extensão com splitext","makedirs(ext, exist_ok=True) e depois shutil.move"]},{"t":"Backup com data","p":"Copie a pasta <code>relatorios</code> inteira para <code>backup_relatorios_AAAA-MM-DD</code> usando a data de <code>hoje</code> e <code>shutil.copytree</code>. Guarde o nome da pasta criada em <code>pasta_backup</code>.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\nfrom datetime import date\nhoje = date(2026, 11, 16)\n","sol":"import shutil\npasta_backup = f\"backup_relatorios_{hoje:%Y-%m-%d}\"\nshutil.copytree(\"relatorios\", pasta_backup)","test":"import os as _o\nassert pasta_backup == \"backup_relatorios_2026-11-16\"\nassert sorted(_o.listdir(pasta_backup)) == [\"r1.pdf\", \"r2.pdf\"], \"Use shutil.copytree\"","h":["f\"{hoje:%Y-%m-%d}\" formata a data","shutil.copytree(origem, destino)"]},{"t":"Desafio: relatório da pasta","p":"Percorra a pasta atual e subpastas (<code>os.walk</code>) e crie <code>por_extensao</code>: <code>{extensão: quantidade}</code> com as chaves em ordem alfabética. Depois grave <code>inventario.txt</code> com uma linha <code>ext: qtd</code> por extensão.","s":"import os\nfor pasta in [\"relatorios\", \"fotos\"]:\n    os.makedirs(pasta, exist_ok=True)\narquivos = {\"vendas_jan.xlsx\": \"x\", \"vendas_fev.xlsx\": \"x\", \"nota.txt\": \"lembrar\", \"foto1.jpg\": \"img\",\n            \"relatorios/r1.pdf\": \"pdf\", \"relatorios/r2.pdf\": \"pdf\", \"fotos/praia.jpg\": \"img\"}\nfor caminho, conteudo in arquivos.items():\n    with open(caminho, \"w\") as f:\n        f.write(conteudo)\n","sol":"import os\ncontagem = {}\nfor raiz, pastas, arquivos in os.walk(\".\"):\n    for nome in arquivos:\n        ext = os.path.splitext(nome)[1].lstrip(\".\").lower()\n        contagem[ext] = contagem.get(ext, 0) + 1\npor_extensao = dict(sorted(contagem.items()))\nwith open(\"inventario.txt\", \"w\", encoding=\"utf-8\") as f:\n    for ext, qtd in por_extensao.items():\n        f.write(f\"{ext}: {qtd}\\n\")","test":"assert por_extensao == {\"jpg\": 2, \"pdf\": 2, \"txt\": 1, \"xlsx\": 2}\nassert list(por_extensao) == [\"jpg\", \"pdf\", \"txt\", \"xlsx\"], \"Chaves em ordem alfabética\"\nassert open(\"inventario.txt\", encoding=\"utf-8\").read().splitlines() == [\"jpg: 2\", \"pdf: 2\", \"txt: 1\", \"xlsx: 2\"]","h":["Conte antes de criar o inventario.txt (senão ele entra na contagem)","dict(sorted(d.items())) ordena pelas chaves"]}]},{"name":"E-mails com Python","short":"relatórios que se enviam sozinhos","cdesc":"montar mensagens (texto, HTML, anexos), enviar por SMTP e ler e-mails recebidos","map":"fluxo","src":"Intermediário • Módulo 27","groups":[["Formas de enviar",[["SMTP (smtplib)","Gmail, Outlook.com e qualquer servidor"],["Outlook (pywin32)","usa o Outlook instalado no Windows"],["APIs (SendGrid etc.)","envio em massa e profissional"]]],["Montar a mensagem",[["EmailMessage()","objeto do e-mail"],["msg[\"Subject\"], [\"From\"], [\"To\"]","cabeçalhos"],["set_content / add_alternative","texto puro / versão HTML"]]],["Anexos",[["add_attachment(bytes, ...)","maintype, subtype, filename"],["Ler o arquivo em \"rb\"","anexo vai como bytes"],["Imagem no corpo","HTML com <img> + anexo"]]],["Enviar (SMTP)",[["smtplib.SMTP(host, 587)","conecta no servidor"],["starttls() + login()","criptografa e autentica"],["send_message(msg) / quit()","envia e encerra"]]],["Segurança",[["Senha de app","o Gmail exige senha de app, não a senha normal"],["Variáveis de ambiente","os.environ[\"EMAIL_SENHA\"]"],["Nunca no código","nem no GitHub"]]],["Ler e-mails",[["imaplib / IMAP","acessar a caixa de entrada"],["email.message_from_string","texto bruto → objeto"],["walk() / get_filename()","percorrer partes e achar anexos"]]]],"hot":["Monte o e-mail com EmailMessage: cabeçalhos com msg[\"Subject\"] etc.","Para HTML, use set_content (texto) + add_alternative(html, subtype=\"html\").","Anexo: leia em modo \"rb\" e use add_attachment com maintype, subtype e filename.","Gmail: porta 587 + starttls() + senha de app.","Senha e usuário vêm de variáveis de ambiente, nunca escritos no código."],"trap":"Colocar a senha direto no código e subir para o GitHub expõe sua conta. Use os.environ (ou um arquivo .env fora do repositório).","examples":[["enviar_email.py","import os, smtplib\nfrom email.message import EmailMessage\n\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Relatório de vendas\"\nmsg[\"From\"] = os.environ[\"EMAIL_USUARIO\"]\nmsg[\"To\"] = \"chefe@empresa.com\"\nmsg.set_content(\"Segue o relatório em anexo.\")\n\nwith open(\"relatorio.csv\", \"rb\") as f:\n    msg.add_attachment(f.read(), maintype=\"text\", subtype=\"csv\", filename=\"relatorio.csv\")\n\nwith smtplib.SMTP(\"smtp.gmail.com\", 587) as servidor:\n    servidor.starttls()\n    servidor.login(os.environ[\"EMAIL_USUARIO\"], os.environ[\"EMAIL_SENHA\"])\n    servidor.send_message(msg)"],["ler_email.py","import email\nfrom email import policy\n\nmsg = email.message_from_string(texto_bruto, policy=policy.default)\nprint(msg[\"Subject\"], msg[\"From\"])\nfor parte in msg.walk():\n    if parte.get_filename():\n        print(\"Anexo:\", parte.get_filename())"]],"ex":[{"t":"Criar a mensagem","p":"Crie <code>msg = EmailMessage()</code> com assunto <code>Relatório diário</code>, remetente <code>remetente</code>, destinatário <code>destino</code> e corpo <code>Bom dia! Segue o relatório.</code>.<br><small class='muted'>Nenhum e-mail sai daqui: o envio é simulado.</small>","s":"remetente = \"relatorios@empresa.com\"\ndestino = \"chefe@empresa.com\"","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Relatório diário\"\nmsg[\"From\"] = remetente\nmsg[\"To\"] = destino\nmsg.set_content(\"Bom dia! Segue o relatório.\")","test":"assert msg[\"Subject\"] == \"Relatório diário\"\nassert (msg[\"From\"], msg[\"To\"]) == (remetente, destino)\nassert msg.get_content().strip() == \"Bom dia! Segue o relatório.\", \"Use msg.set_content(...)\"","h":["from email.message import EmailMessage","Cabeçalhos funcionam como dicionário: msg[\"Subject\"] = ..."]},{"t":"Vários destinatários","p":"Crie a mensagem <code>msg</code> com assunto <code>Aviso</code>, corpo <code>Reunião às 10h</code> e envie para todos os e-mails da lista <code>equipe</code> no campo <code>To</code> (separados por <code>, </code>).","s":"equipe = [\"ana@x.com\", \"leo@x.com\", \"bia@x.com\"]","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Aviso\"\nmsg[\"To\"] = \", \".join(equipe)\nmsg.set_content(\"Reunião às 10h\")","test":"assert msg[\"To\"] == \"ana@x.com, leo@x.com, bia@x.com\", \"Use \\\", \\\".join(equipe)\"\nassert msg[\"Subject\"] == \"Aviso\"","h":["\", \".join(lista)","msg[\"To\"] aceita vários endereços separados por vírgula"]},{"t":"Corpo com f-string","p":"Monte <code>msg</code> com assunto <code>Faturamento</code> e corpo <code>O faturamento foi de R$ 12,345.60</code>, formatando <code>faturamento</code>.","s":"faturamento = 12345.6","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Faturamento\"\nmsg.set_content(f\"O faturamento foi de R$ {faturamento:,.2f}\")","test":"assert msg.get_content().strip() == \"O faturamento foi de R$ 12,345.60\"\nassert rodar(faturamento=10)[\"msg\"].get_content().strip() == \"O faturamento foi de R$ 10.00\", \"Use a variável\"","h":["f\"... {faturamento:,.2f}\"","msg.set_content(texto)"]},{"t":"Credenciais do ambiente","p":"Leia o usuário e a senha das variáveis de ambiente <code>EMAIL_USUARIO</code> e <code>EMAIL_SENHA</code> em <code>usuario</code> e <code>senha</code>. <b>Não</b> escreva a senha no código.","s":"import os\nos.environ[\"EMAIL_USUARIO\"] = \"relatorios@empresa.com\"\nos.environ[\"EMAIL_SENHA\"] = \"senha-de-app-123\"\n","sol":"usuario = os.environ[\"EMAIL_USUARIO\"]\nsenha = os.environ[\"EMAIL_SENHA\"]","test":"assert (usuario, senha) == (\"relatorios@empresa.com\", \"senha-de-app-123\")\nassert \"senha-de-app-123\" not in codigo, \"A senha não pode estar escrita no código\"","h":["os.environ[\"NOME\"]","os.environ.get(\"NOME\") devolve None se não existir"]},{"t":"Enviar por SMTP","p":"Envie <code>msg</code> (já pronta) pelo Gmail: <code>smtplib.SMTP(\"smtp.gmail.com\", 587)</code>, <code>starttls()</code>, <code>login</code> com as variáveis de ambiente e <code>send_message</code>. Feche com <code>quit()</code> (ou use <code>with</code>).","s":"import os\nos.environ[\"EMAIL_USUARIO\"] = \"relatorios@empresa.com\"\nos.environ[\"EMAIL_SENHA\"] = \"senha-de-app-123\"\nfrom email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Teste\"\nmsg[\"To\"] = \"chefe@empresa.com\"\nmsg.set_content(\"ok\")\n","sol":"import smtplib\nservidor = smtplib.SMTP(\"smtp.gmail.com\", 587)\nservidor.starttls()\nservidor.login(os.environ[\"EMAIL_USUARIO\"], os.environ[\"EMAIL_SENHA\"])\nservidor.send_message(msg)\nservidor.quit()","test":"env = _smtp.ENVIADOS\nassert len(env) == 1, \"Chame send_message(msg) uma vez\"\ns = env[0][\"servidor\"]\nassert (s.host, s.port) == (\"smtp.gmail.com\", 587), \"smtplib.SMTP(\\\"smtp.gmail.com\\\", 587)\"\nassert s.tls, \"Chame starttls() antes do login\"\nassert s.senha == \"senha-de-app-123\" and \"senha-de-app-123\" not in codigo, \"Faça login com os.environ[\\\"EMAIL_SENHA\\\"]\"\nassert s.fechado, \"Feche a conexão com quit() ou use with\"","h":["Sequência: SMTP(...) → starttls() → login(...) → send_message(msg)","with smtplib.SMTP(...) as servidor: fecha sozinho"]},{"t":"Versão em HTML","p":"Crie <code>msg</code> com assunto <code>Promoção</code>, texto puro <code>Veja nossas ofertas</code> e uma versão HTML <code>&lt;h1&gt;Ofertas&lt;/h1&gt;</code> com <code>add_alternative(..., subtype=\"html\")</code>.","s":"","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Promoção\"\nmsg.set_content(\"Veja nossas ofertas\")\nmsg.add_alternative(\"<h1>Ofertas</h1>\", subtype=\"html\")","test":"assert msg.get_content_type() == \"multipart/alternative\", \"Use set_content e depois add_alternative\"\ntipos = [p.get_content_type() for p in msg.iter_parts()]\nassert tipos == [\"text/plain\", \"text/html\"]\nassert \"<h1>Ofertas</h1>\" in msg.get_body((\"html\",)).get_content()","h":["Primeiro set_content (texto), depois add_alternative (HTML)","subtype=\"html\""]},{"t":"Anexar arquivo","p":"O arquivo <code>vendas.csv</code> existe na pasta. Crie <code>msg</code> com assunto <code>Vendas</code>, corpo <code>Segue anexo</code> e anexe o arquivo (leia em <code>\"rb\"</code>, <code>maintype=\"text\"</code>, <code>subtype=\"csv\"</code>, <code>filename=\"vendas.csv\"</code>).","s":"with open(\"vendas.csv\", \"w\") as f:\n    f.write(\"produto,valor\\nCafé,10\\n\")","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Vendas\"\nmsg.set_content(\"Segue anexo\")\nwith open(\"vendas.csv\", \"rb\") as f:\n    msg.add_attachment(f.read(), maintype=\"text\", subtype=\"csv\", filename=\"vendas.csv\")","test":"anexos = list(msg.iter_attachments())\nassert len(anexos) == 1, \"Use msg.add_attachment(...)\"\nassert anexos[0].get_filename() == \"vendas.csv\"\nassert \"Café,10\" in anexos[0].get_payload(decode=True).decode(\"utf-8\"), \"Anexe o conteúdo do arquivo\"","h":["Leia como bytes: open(..., \"rb\")","add_attachment(dados, maintype=..., subtype=..., filename=...)"]},{"t":"Ler um e-mail recebido","p":"<code>bruto</code> é o texto de um e-mail recebido. Converta com <code>email.message_from_string(bruto, policy=policy.default)</code> e guarde em <code>assunto</code> e <code>remetente</code> o assunto e o endereço do remetente (só o e-mail).","s":"bruto = \"\"\"From: Financeiro <financeiro@fornecedor.com>\nTo: compras@empresa.com\nSubject: Nota fiscal 4521\nDate: Mon, 16 Nov 2026 09:30:00 -0300\nMIME-Version: 1.0\nContent-Type: multipart/mixed; boundary=\"XYZ\"\n\n--XYZ\nContent-Type: text/plain; charset=\"utf-8\"\n\nSegue a nota fiscal do pedido 4521. Valor: R$ 1.250,00.\n--XYZ\nContent-Type: text/csv; name=\"itens.csv\"\nContent-Disposition: attachment; filename=\"itens.csv\"\n\nproduto,qtd\nPapel A4,10\nToner,2\n--XYZ--\n\"\"\"\n","sol":"import email\nfrom email import policy\nfrom email.utils import parseaddr\nmsg = email.message_from_string(bruto, policy=policy.default)\nassunto = msg[\"Subject\"]\nremetente = parseaddr(msg[\"From\"])[1]","test":"assert assunto == \"Nota fiscal 4521\"\nassert remetente == \"financeiro@fornecedor.com\", \"Só o endereço: use email.utils.parseaddr\"","h":["msg[\"Subject\"] e msg[\"From\"]","parseaddr(\"Nome <a@b.com>\") devolve (\"Nome\", \"a@b.com\")"]},{"t":"Extrair anexos","p":"Do e-mail em <code>bruto</code>, encontre os anexos e salve cada um na pasta atual com o nome original. Guarde os nomes salvos na lista <code>salvos</code>.","s":"bruto = \"\"\"From: Financeiro <financeiro@fornecedor.com>\nTo: compras@empresa.com\nSubject: Nota fiscal 4521\nDate: Mon, 16 Nov 2026 09:30:00 -0300\nMIME-Version: 1.0\nContent-Type: multipart/mixed; boundary=\"XYZ\"\n\n--XYZ\nContent-Type: text/plain; charset=\"utf-8\"\n\nSegue a nota fiscal do pedido 4521. Valor: R$ 1.250,00.\n--XYZ\nContent-Type: text/csv; name=\"itens.csv\"\nContent-Disposition: attachment; filename=\"itens.csv\"\n\nproduto,qtd\nPapel A4,10\nToner,2\n--XYZ--\n\"\"\"\n","sol":"import email\nfrom email import policy\nmsg = email.message_from_string(bruto, policy=policy.default)\nsalvos = []\nfor parte in msg.iter_attachments():\n    nome = parte.get_filename()\n    with open(nome, \"wb\") as f:\n        f.write(parte.get_payload(decode=True))\n    salvos.append(nome)","test":"assert salvos == [\"itens.csv\"]\nassert open(\"itens.csv\", encoding=\"utf-8\").read().splitlines()[:2] == [\"produto,qtd\", \"Papel A4,10\"], \"Grave o conteúdo do anexo\"","h":["msg.iter_attachments() percorre só os anexos","parte.get_payload(decode=True) devolve os bytes"]},{"t":"Extrair valor do corpo","p":"Do e-mail em <code>bruto</code>, leia o texto do corpo (<code>msg.get_body((\"plain\",)).get_content()</code>) e extraia o valor em reais como <code>float</code> em <code>valor</code> (R$ 1.250,00 → 1250.0).","s":"bruto = \"\"\"From: Financeiro <financeiro@fornecedor.com>\nTo: compras@empresa.com\nSubject: Nota fiscal 4521\nDate: Mon, 16 Nov 2026 09:30:00 -0300\nMIME-Version: 1.0\nContent-Type: multipart/mixed; boundary=\"XYZ\"\n\n--XYZ\nContent-Type: text/plain; charset=\"utf-8\"\n\nSegue a nota fiscal do pedido 4521. Valor: R$ 1.250,00.\n--XYZ\nContent-Type: text/csv; name=\"itens.csv\"\nContent-Disposition: attachment; filename=\"itens.csv\"\n\nproduto,qtd\nPapel A4,10\nToner,2\n--XYZ--\n\"\"\"\n","sol":"import email, re\nfrom email import policy\nmsg = email.message_from_string(bruto, policy=policy.default)\ncorpo = msg.get_body((\"plain\",)).get_content()\ntexto = re.search(r\"R\\$ ([\\d.,]+\\d)\", corpo).group(1)\nvalor = float(texto.replace(\".\", \"\").replace(\",\", \".\"))","test":"assert valor == 1250.0, \"Troque . de milhar por nada e , decimal por .\"","h":["Encontre o trecho depois de \"R$ \" (com split ou re)","\"1.250,00\".replace(\".\", \"\").replace(\",\", \".\")"]},{"t":"Função de envio","p":"Crie <code>enviar(destino, assunto, corpo)</code> que monta a mensagem (From = <code>EMAIL_USUARIO</code>) e envia por <code>smtplib.SMTP(\"smtp.gmail.com\", 587)</code> com <code>starttls</code> e login pelas variáveis de ambiente. Depois chame <code>enviar(\"ana@x.com\", \"Oi\", \"Teste\")</code>.","s":"import os\nos.environ[\"EMAIL_USUARIO\"] = \"relatorios@empresa.com\"\nos.environ[\"EMAIL_SENHA\"] = \"senha-de-app-123\"\n","sol":"import smtplib\nfrom email.message import EmailMessage\n\ndef enviar(destino, assunto, corpo):\n    msg = EmailMessage()\n    msg[\"Subject\"] = assunto\n    msg[\"From\"] = os.environ[\"EMAIL_USUARIO\"]\n    msg[\"To\"] = destino\n    msg.set_content(corpo)\n    with smtplib.SMTP(\"smtp.gmail.com\", 587) as servidor:\n        servidor.starttls()\n        servidor.login(os.environ[\"EMAIL_USUARIO\"], os.environ[\"EMAIL_SENHA\"])\n        servidor.send_message(msg)\n\nenviar(\"ana@x.com\", \"Oi\", \"Teste\")","test":"e = _smtp.ENVIADOS\nassert len(e) == 1, \"Chame enviar(...) uma vez\"\nm = e[0][\"msg\"]\nassert (m[\"To\"], m[\"Subject\"], m[\"From\"]) == (\"ana@x.com\", \"Oi\", \"relatorios@empresa.com\")\nassert e[0][\"servidor\"].tls and e[0][\"servidor\"].fechado\nenviar(\"leo@x.com\", \"A\", \"B\")\nassert _smtp.ENVIADOS[-1][\"msg\"][\"To\"] == \"leo@x.com\", \"Use o parâmetro destino\"\nassert \"senha-de-app-123\" not in codigo","h":["Monte a mensagem dentro da função","with smtplib.SMTP(...) as servidor:"]},{"t":"E-mail personalizado em massa","p":"Para cada cliente de <code>clientes</code> (lista de dicts com <code>nome</code>, <code>email</code> e <code>valor</code>), envie um e-mail com assunto <code>Sua fatura</code> e corpo <code>Olá, NOME! Sua fatura é de R$ VALOR.</code> (valor com 2 casas). Use <b>uma</b> conexão SMTP para todos.","s":"import os\nos.environ[\"EMAIL_USUARIO\"] = \"relatorios@empresa.com\"\nos.environ[\"EMAIL_SENHA\"] = \"senha-de-app-123\"\nclientes = [{\"nome\": \"Ana\", \"email\": \"ana@x.com\", \"valor\": 150}, {\"nome\": \"Leo\", \"email\": \"leo@x.com\", \"valor\": 89.9}]\n","sol":"import smtplib\nfrom email.message import EmailMessage\nwith smtplib.SMTP(\"smtp.gmail.com\", 587) as servidor:\n    servidor.starttls()\n    servidor.login(os.environ[\"EMAIL_USUARIO\"], os.environ[\"EMAIL_SENHA\"])\n    for c in clientes:\n        msg = EmailMessage()\n        msg[\"Subject\"] = \"Sua fatura\"\n        msg[\"From\"] = os.environ[\"EMAIL_USUARIO\"]\n        msg[\"To\"] = c[\"email\"]\n        msg.set_content(f\"Olá, {c['nome']}! Sua fatura é de R$ {c['valor']:.2f}.\")\n        servidor.send_message(msg)","test":"e = _smtp.ENVIADOS\nassert [x[\"msg\"][\"To\"] for x in e] == [\"ana@x.com\", \"leo@x.com\"], \"Um e-mail por cliente\"\nassert e[1][\"msg\"].get_content().strip() == \"Olá, Leo! Sua fatura é de R$ 89.90.\"\nassert e[0][\"servidor\"] is e[1][\"servidor\"], \"Use a mesma conexão SMTP para todos (abra antes do for)\"","h":["Abra a conexão antes do for e envie dentro dele","Crie uma EmailMessage nova a cada cliente"]},{"t":"Imagem no corpo do e-mail","p":"Crie <code>msg</code> com texto <code>Veja o gráfico</code> e versão HTML contendo <code>&lt;img src=\"cid:grafico\"&gt;</code>. Anexe <code>grafico.png</code> à parte HTML com <code>add_related(..., maintype=\"image\", subtype=\"png\", cid=\"&lt;grafico&gt;\")</code>.","s":"with open(\"grafico.png\", \"wb\") as f:\n    f.write(b\"\\x89PNG\\r\\n\\x1a\\nfake\")","sol":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Gráfico\"\nmsg.set_content(\"Veja o gráfico\")\nmsg.add_alternative('<p>Vendas:</p><img src=\"cid:grafico\">', subtype=\"html\")\nwith open(\"grafico.png\", \"rb\") as f:\n    msg.get_payload()[1].add_related(f.read(), maintype=\"image\", subtype=\"png\", cid=\"<grafico>\")","test":"html = msg.get_body((\"related\",))\nassert html is not None, \"Use add_related na parte HTML\"\npartes = [p.get_content_type() for p in html.iter_parts()]\nassert partes == [\"text/html\", \"image/png\"], \"A imagem fica junto do HTML (multipart/related)\"\nassert \"cid:grafico\" in html.get_body((\"html\",)).get_content()\nassert [p for p in html.iter_parts()][1][\"Content-ID\"] == \"<grafico>\"","h":["A parte HTML é msg.get_payload()[1] depois do add_alternative","No HTML use src=\"cid:grafico\" e no anexo cid=\"<grafico>\""]},{"t":"Filtrar caixa de entrada","p":"<code>caixa</code> é uma lista de e-mails brutos. Crie <code>notas</code>: lista com o <b>assunto</b> dos e-mails cujo assunto contém <code>Nota fiscal</code> e que têm pelo menos um anexo.","s":"bruto = \"\"\"From: Financeiro <financeiro@fornecedor.com>\nTo: compras@empresa.com\nSubject: Nota fiscal 4521\nDate: Mon, 16 Nov 2026 09:30:00 -0300\nMIME-Version: 1.0\nContent-Type: multipart/mixed; boundary=\"XYZ\"\n\n--XYZ\nContent-Type: text/plain; charset=\"utf-8\"\n\nSegue a nota fiscal do pedido 4521. Valor: R$ 1.250,00.\n--XYZ\nContent-Type: text/csv; name=\"itens.csv\"\nContent-Disposition: attachment; filename=\"itens.csv\"\n\nproduto,qtd\nPapel A4,10\nToner,2\n--XYZ--\n\"\"\"\nsimples = \"From: a@b.com\\nSubject: Nota fiscal 9\\n\\nsem anexo\"\noutro = bruto.replace(\"Nota fiscal 4521\", \"Boleto 77\")\ncaixa = [bruto, simples, outro]\n","sol":"import email\nfrom email import policy\nnotas = []\nfor texto in caixa:\n    m = email.message_from_string(texto, policy=policy.default)\n    if \"Nota fiscal\" in m[\"Subject\"] and list(m.iter_attachments()):\n        notas.append(m[\"Subject\"])","test":"assert notas == [\"Nota fiscal 4521\"], \"Só a nota fiscal COM anexo\"","h":["Converta cada texto com message_from_string","list(m.iter_attachments()) vazia = sem anexo"]},{"t":"Desafio: relatório automático","p":"Calcule a partir de <code>vendas</code> (dict loja → valor) o <code>total</code>, gere <code>resumo.csv</code> (<code>loja,valor</code>), monte a mensagem para <code>destino</code> com assunto <code>Resumo de vendas</code>, corpo <code>Total: R$ X</code> (2 casas, milhar com vírgula) e o CSV anexado, e envie pelo SMTP do Gmail com credenciais do ambiente.","s":"import os\nos.environ[\"EMAIL_USUARIO\"] = \"relatorios@empresa.com\"\nos.environ[\"EMAIL_SENHA\"] = \"senha-de-app-123\"\nvendas = {\"Recife\": 15200.5, \"Olinda\": 8300, \"Caruaru\": 4999.5}\ndestino = \"diretoria@empresa.com\"\n","sol":"import csv, smtplib\nfrom email.message import EmailMessage\ntotal = sum(vendas.values())\nwith open(\"resumo.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    w = csv.writer(f)\n    w.writerow([\"loja\", \"valor\"])\n    w.writerows(vendas.items())\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Resumo de vendas\"\nmsg[\"From\"] = os.environ[\"EMAIL_USUARIO\"]\nmsg[\"To\"] = destino\nmsg.set_content(f\"Total: R$ {total:,.2f}\")\nwith open(\"resumo.csv\", \"rb\") as f:\n    msg.add_attachment(f.read(), maintype=\"text\", subtype=\"csv\", filename=\"resumo.csv\")\nwith smtplib.SMTP(\"smtp.gmail.com\", 587) as s:\n    s.starttls()\n    s.login(os.environ[\"EMAIL_USUARIO\"], os.environ[\"EMAIL_SENHA\"])\n    s.send_message(msg)","test":"assert total == 28500.0\ne = _smtp.ENVIADOS\nassert len(e) == 1, \"Envie uma mensagem\"\nm = e[0][\"msg\"]\nassert m[\"To\"] == destino and m[\"Subject\"] == \"Resumo de vendas\"\nassert m.get_body((\"plain\",)).get_content().strip() == \"Total: R$ 28,500.00\"\na = list(m.iter_attachments())\nassert len(a) == 1 and a[0].get_filename() == \"resumo.csv\"\nassert a[0].get_payload(decode=True).decode(\"utf-8\").splitlines()[:2] == [\"loja,valor\", \"Recife,15200.5\"]\nassert e[0][\"servidor\"].tls and \"senha-de-app-123\" not in codigo","h":["Etapas: calcular → gravar CSV → montar mensagem → anexar → enviar","Reaproveite o que fez nos exercícios anteriores"]}]},{"name":"Python + SQL (banco de dados)","short":"CRUD direto do Python","cdesc":"conectar, executar comandos, parâmetros seguros, commit, CRUD e pandas.read_sql","map":"fluxo","src":"Intermediário • Módulo 28","pkgs":["sqlite3"],"groups":[["Conectar",[["pyodbc.connect(...)","SQL Server (no seu PC, com o driver ODBC)"],["sqlite3.connect(arquivo)","banco em arquivo (usado aqui)"],["conexao.cursor()","objeto que executa os comandos"]]],["CRUD",[["Create: INSERT INTO","inserir linhas"],["Read: SELECT","fetchone, fetchall"],["Update / Delete","UPDATE ... SET / DELETE ... WHERE"]]],["Parâmetros",[["? no SQL","execute(sql, (v1, v2)) — pyodbc e sqlite3"],["Nunca f-string com dados","evita SQL Injection"],["executemany","vários registros de uma vez"]]],["Confirmar e fechar",[["conexao.commit()","grava INSERT/UPDATE/DELETE"],["rollback()","desfaz se der erro"],["cursor.close() / conexao.close()","libera a conexão"]]],["Com pandas",[["pd.read_sql(sql, conexao)","consulta direto num DataFrame"],["df.to_sql(...)","grava um DataFrame numa tabela"],["SQLAlchemy","ORM: tabelas como classes Python"]]]],"hot":["O fluxo é sempre: conectar → cursor → execute → (commit) → fechar.","SELECT não precisa de commit; INSERT, UPDATE e DELETE precisam.","Use ? como parâmetro: execute(\"... WHERE id = ?\", (id,)). Nunca monte o SQL com f-string.","fetchall() devolve uma lista de tuplas; fetchone() devolve uma tupla (ou None).","UPDATE e DELETE sem WHERE afetam a tabela INTEIRA.","Senha do banco fica em variável de ambiente, não na string de conexão do código."],"trap":"(id) não é tupla! Para um único parâmetro escreva (id,) com vírgula, senão o execute dá erro.","examples":[["crud_sqlite.py","import sqlite3\n\nconexao = sqlite3.connect(\"loja.db\")\ncursor = conexao.cursor()\ncursor.execute(\"INSERT INTO Clientes (nome, email) VALUES (?, ?)\", (\"Ana\", \"ana@x.com\"))\nconexao.commit()\n\ncursor.execute(\"SELECT id, nome FROM Clientes WHERE nome LIKE ?\", (\"A%\",))\nfor id_, nome in cursor.fetchall():\n    print(id_, nome)\n\ncursor.close()\nconexao.close()"],["sql_server_no_seu_pc.py","# No seu PC, com SQL Server (pip install pyodbc):\nimport os, pyodbc\ndados_conexao = (\n    \"Driver={ODBC Driver 18 for SQL Server};\"\n    \"Server=localhost;Database=Loja;\"\n    f\"UID={os.environ['DB_USER']};PWD={os.environ['DB_PASS']};TrustServerCertificate=yes\"\n)\nconexao = pyodbc.connect(dados_conexao)\n# O resto (cursor, execute com ?, commit) é IGUAL ao sqlite3.\n\nimport pandas as pd\ndf = pd.read_sql(\"SELECT * FROM Vendas\", conexao)"]],"ex":[{"t":"Primeira consulta","p":"O banco já está conectado em <code>conexao</code> e <code>cursor</code>. Execute <code>SELECT nome FROM Clientes</code> e guarde em <code>linhas</code> o resultado de <code>fetchall()</code>.<br><small class='muted'>Aqui usamos SQLite no navegador; no SQL Server com pyodbc o código é o mesmo.</small>","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"cursor.execute(\"SELECT nome FROM Clientes\")\nlinhas = cursor.fetchall()","test":"assert linhas == [(\"Ana Souza\",), (\"Leo Lima\",), (\"Bia Rocha\",), (\"Caio Melo\",)], \"fetchall() devolve lista de tuplas\"","h":["cursor.execute(\"SELECT ...\")","linhas = cursor.fetchall()"]},{"t":"Lista de nomes","p":"Transforme o resultado de <code>SELECT nome FROM Clientes ORDER BY nome</code> numa lista simples de textos em <code>nomes</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"cursor.execute(\"SELECT nome FROM Clientes ORDER BY nome\")\nnomes = [linha[0] for linha in cursor.fetchall()]","test":"assert nomes == [\"Ana Souza\", \"Bia Rocha\", \"Caio Melo\", \"Leo Lima\"], \"Pegue o item [0] de cada tupla\"","h":["Cada linha é uma tupla com uma coluna","[linha[0] for linha in cursor.fetchall()]"]},{"t":"Um único registro","p":"Busque o e-mail do cliente de <code>id = 2</code> com <code>fetchone()</code> e guarde só o texto em <code>email</code>. Use parâmetro <code>?</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"cursor.execute(\"SELECT email FROM Clientes WHERE id = ?\", (2,))\nemail = cursor.fetchone()[0]","test":"assert email == \"leo@x.com\"\nassert \"?\" in codigo, \"Use o parâmetro ? no WHERE\"","h":["fetchone() devolve uma tupla","Um parâmetro: (2,) com vírgula"]},{"t":"Inserir com parâmetros","p":"Insira o cliente com <code>nome</code>, <code>email</code> e <code>cidade</code> (variáveis) na tabela <code>Clientes</code> usando <code>?</code> e confirme com <code>commit()</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nnome = \"Duda Alves\"\nemail = \"duda@x.com\"\ncidade = \"Paulista\"\n","sol":"cursor.execute(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", (nome, email, cidade))\nconexao.commit()","test":"assert conexao.in_transaction is False, \"Confirme com conexao.commit()\"\nc = conexao.execute(\"SELECT nome, email, cidade FROM Clientes WHERE id = 5\").fetchone()\nassert c == (\"Duda Alves\", \"duda@x.com\", \"Paulista\")\nassert \"Duda\" not in codigo, \"Use as variáveis com ?, não valores fixos no SQL\"","h":["INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)","Passe a tupla (nome, email, cidade) e depois commit()"]},{"t":"Contar registros","p":"Use <code>SELECT COUNT(*) FROM Vendas</code> para guardar em <code>qtd</code> o número de vendas (inteiro).","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"cursor.execute(\"SELECT COUNT(*) FROM Vendas\")\nqtd = cursor.fetchone()[0]","test":"assert qtd == 6","h":["COUNT(*) conta as linhas","fetchone()[0]"]},{"t":"Atualizar dado","p":"Atualize o e-mail da cliente <code>Bia Rocha</code> (que está vazio) para <code>novo_email</code>, filtrando pelo nome com <code>?</code>. Guarde em <code>afetadas</code> o <code>cursor.rowcount</code> e faça <code>commit</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nnovo_email = \"bia@x.com\"\n","sol":"cursor.execute(\"UPDATE Clientes SET email = ? WHERE nome = ?\", (novo_email, \"Bia Rocha\"))\nafetadas = cursor.rowcount\nconexao.commit()","test":"assert afetadas == 1, \"Só uma linha deve ser alterada (não esqueça o WHERE)\"\nassert conexao.execute(\"SELECT email FROM Clientes WHERE nome = 'Bia Rocha'\").fetchone()[0] == \"bia@x.com\"\nassert conexao.execute(\"SELECT COUNT(*) FROM Clientes WHERE email = 'bia@x.com'\").fetchone()[0] == 1\nassert not conexao.in_transaction, \"Faça commit()\"","h":["UPDATE Clientes SET email = ? WHERE nome = ?","rowcount = quantas linhas mudaram"]},{"t":"Excluir com segurança","p":"Exclua as vendas do produto <code>produto</code> (variável) com <code>DELETE ... WHERE</code> e <code>?</code>. Faça <code>commit</code> e guarde em <code>restantes</code> quantas vendas sobraram.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nproduto = \"Mouse\"\n","sol":"cursor.execute(\"DELETE FROM Vendas WHERE produto = ?\", (produto,))\nconexao.commit()\ncursor.execute(\"SELECT COUNT(*) FROM Vendas\")\nrestantes = cursor.fetchone()[0]","test":"assert restantes == 4, \"6 vendas - 2 de Mouse = 4\"\nassert rodar(produto=\"Notebook\")[\"restantes\"] == 4\nassert \"?\" in codigo","h":["DELETE FROM Vendas WHERE produto = ?","(produto,) é uma tupla com um item"]},{"t":"Vários registros de uma vez","p":"Insira todas as vendas de <code>novas</code> (lista de tuplas <code>(cliente_id, produto, valor, data)</code>) com <code>executemany</code> e faça <code>commit</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nnovas = [(4, \"Cabo HDMI\", 45, \"2026-04-01\"), (1, \"Webcam\", 230, \"2026-04-02\")]\n","sol":"cursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", novas)\nconexao.commit()","test":"assert conexao.execute(\"SELECT COUNT(*) FROM Vendas\").fetchone()[0] == 8\nassert conexao.execute(\"SELECT produto FROM Vendas WHERE id = 8\").fetchone()[0] == \"Webcam\"\nassert \"executemany\" in codigo and not conexao.in_transaction","h":["cursor.executemany(sql, lista_de_tuplas)","Um ? para cada coluna"]},{"t":"Consulta com JOIN","p":"Guarde em <code>compras</code> a lista de tuplas <code>(nome do cliente, produto, valor)</code> das vendas acima de <code>minimo</code>, ordenadas pelo valor (maior primeiro). Use <code>JOIN</code> entre <code>Vendas</code> e <code>Clientes</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nminimo = 1000\n","sol":"cursor.execute(\"\"\"\n    SELECT c.nome, v.produto, v.valor\n    FROM Vendas v\n    JOIN Clientes c ON c.id = v.cliente_id\n    WHERE v.valor > ?\n    ORDER BY v.valor DESC\n\"\"\", (minimo,))\ncompras = cursor.fetchall()","test":"assert compras == [(\"Ana Souza\", \"Notebook\", 3500.0), (\"Caio Melo\", \"Notebook\", 3400.0), (\"Leo Lima\", \"Monitor\", 1200.0)]\nassert len(rodar(minimo=3450)[\"compras\"]) == 1, \"Use o parâmetro minimo\"","h":["JOIN Clientes c ON c.id = v.cliente_id","WHERE v.valor > ? ORDER BY v.valor DESC"]},{"t":"read_sql do pandas","p":"Use <code>pd.read_sql</code> para carregar <code>SELECT produto, valor FROM Vendas</code> num DataFrame <code>df</code> e guarde em <code>total_produto</code> a soma de valor por produto (Series ordenada pelo índice, como o groupby faz).","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nimport pandas as pd\n","sol":"df = pd.read_sql(\"SELECT produto, valor FROM Vendas\", conexao)\ntotal_produto = df.groupby(\"produto\")[\"valor\"].sum()","test":"assert list(df.columns) == [\"produto\", \"valor\"] and len(df) == 6\nassert total_produto.to_dict() == {\"Monitor\": 1200.0, \"Mouse\": 160.0, \"Notebook\": 6900.0, \"Teclado\": 150.0}","h":["pd.read_sql(sql, conexao)","df.groupby(\"produto\")[\"valor\"].sum()"]},{"t":"Agregação no SQL","p":"Calcule no próprio SQL o total vendido por cidade (<code>GROUP BY</code>), do maior para o menor, e guarde em <code>por_cidade</code> como dicionário <code>{cidade: total}</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"cursor.execute(\"\"\"\n    SELECT c.cidade, SUM(v.valor) AS total\n    FROM Vendas v JOIN Clientes c ON c.id = v.cliente_id\n    GROUP BY c.cidade\n    ORDER BY total DESC\n\"\"\")\npor_cidade = dict(cursor.fetchall())","test":"assert por_cidade == {\"Recife\": 3730.0, \"Caruaru\": 3400.0, \"Olinda\": 1280.0}\nassert list(por_cidade) == [\"Recife\", \"Caruaru\", \"Olinda\"], \"Ordene do maior para o menor\"","h":["SUM(v.valor) ... GROUP BY c.cidade","dict(lista de tuplas de 2 itens) vira dicionário"]},{"t":"Transação com rollback","p":"Crie <code>inserir_lote(lote)</code> que insere todas as vendas de uma lista de tuplas <code>(cliente_id, produto, valor, data)</code>. Se <b>qualquer</b> linha tiver produto vazio (<code>None</code> ou <code>\"\"</code>), gere <code>ValueError</code>, faça <code>rollback()</code> para não gravar nada e retorne <code>False</code>. Se tudo der certo, faça <code>commit()</code> e retorne <code>True</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\nlote = [(1, \"Pendrive\", 50, \"2026-05-01\"), (2, None, 20, \"2026-05-02\")]\n","sol":"def inserir_lote(lote):\n    try:\n        for cliente_id, produto, valor, data in lote:\n            if not produto:\n                raise ValueError(\"Produto vazio\")\n            cursor.execute(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", (cliente_id, produto, valor, data))\n        conexao.commit()\n        return True\n    except ValueError:\n        conexao.rollback()\n        return False\n\nresultado = inserir_lote(lote)","test":"assert inserir_lote([(1, \"Pendrive\", 50, \"2026-05-01\"), (2, None, 20, \"2026-05-02\")]) is False\nassert conexao.execute(\"SELECT COUNT(*) FROM Vendas\").fetchone()[0] == 6, \"Com rollback, nada do lote é gravado\"\nassert inserir_lote([(1, \"Cabo\", 10, \"2026-05-03\")]) is True\nassert conexao.execute(\"SELECT COUNT(*) FROM Vendas\").fetchone()[0] == 7","h":["try: ... commit() / except: rollback()","rollback() desfaz o que não foi confirmado"]},{"t":"Evitar SQL Injection","p":"A função <code>buscar_cliente(nome)</code> abaixo é vulnerável. Reescreva-a com parâmetro <code>?</code> (mesmo nome, retornando <code>fetchall()</code>).<pre class='code'>def buscar_cliente(nome):\n    cursor.execute(f\"SELECT id, nome FROM Clientes WHERE nome = '{nome}'\")\n    return cursor.fetchall()</pre>","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"def buscar_cliente(nome):\n    cursor.execute(\"SELECT id, nome FROM Clientes WHERE nome = ?\", (nome,))\n    return cursor.fetchall()","test":"assert buscar_cliente(\"Leo Lima\") == [(2, \"Leo Lima\")]\nassert buscar_cliente(\"x' OR '1'='1\") == [], \"Com ? o texto malicioso é tratado como dado, não como SQL\"\nassert \"f\\\"SELECT\" not in codigo and \"?\" in codigo","h":["Troque a f-string por ? no SQL","execute(sql, (nome,))"]},{"t":"Criar tabela e importar","p":"Crie a tabela <code>Produtos</code> (<code>id INTEGER PRIMARY KEY</code>, <code>nome TEXT</code>, <code>preco REAL</code>) <b>se não existir</b> e importe <code>catalogo</code> (lista de dicts) com <code>executemany</code>. Faça <code>commit</code>.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\ncatalogo = [{\"nome\": \"Café\", \"preco\": 18.9}, {\"nome\": \"Chá\", \"preco\": 9.5}]\n","sol":"cursor.execute(\"CREATE TABLE IF NOT EXISTS Produtos (id INTEGER PRIMARY KEY, nome TEXT, preco REAL)\")\ncursor.executemany(\"INSERT INTO Produtos (nome, preco) VALUES (?, ?)\", [(p[\"nome\"], p[\"preco\"]) for p in catalogo])\nconexao.commit()","test":"assert conexao.execute(\"SELECT nome, preco FROM Produtos ORDER BY id\").fetchall() == [(\"Café\", 18.9), (\"Chá\", 9.5)]\nassert \"IF NOT EXISTS\" in codigo.upper()\nassert not conexao.in_transaction","h":["CREATE TABLE IF NOT EXISTS ...","Converta os dicts em tuplas para o executemany"]},{"t":"Desafio: mini CRUD","p":"Crie 4 funções: <code>criar(nome, email)</code> → retorna o id novo (<code>cursor.lastrowid</code>); <code>ler(id)</code> → tupla <code>(nome, email)</code> ou <code>None</code>; <code>atualizar(id, email)</code> → <code>True</code> se alterou; <code>excluir(id)</code> → <code>True</code> se excluiu. Todas com <code>?</code> e <code>commit</code> quando alterarem dados.","s":"import sqlite3\nconexao = sqlite3.connect(\":memory:\")\ncursor = conexao.cursor()\ncursor.execute(\"CREATE TABLE Clientes (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT, cidade TEXT)\")\ncursor.execute(\"CREATE TABLE Vendas (id INTEGER PRIMARY KEY, cliente_id INTEGER, produto TEXT, valor REAL, data TEXT)\")\ncursor.executemany(\"INSERT INTO Clientes (nome, email, cidade) VALUES (?, ?, ?)\", [\n    (\"Ana Souza\", \"ana@x.com\", \"Recife\"), (\"Leo Lima\", \"leo@x.com\", \"Olinda\"),\n    (\"Bia Rocha\", None, \"Recife\"), (\"Caio Melo\", \"caio@x.com\", \"Caruaru\")])\ncursor.executemany(\"INSERT INTO Vendas (cliente_id, produto, valor, data) VALUES (?, ?, ?, ?)\", [\n    (1, \"Notebook\", 3500, \"2026-01-10\"), (1, \"Mouse\", 80, \"2026-01-12\"), (2, \"Monitor\", 1200, \"2026-02-03\"),\n    (3, \"Teclado\", 150, \"2026-02-15\"), (2, \"Mouse\", 80, \"2026-03-01\"), (4, \"Notebook\", 3400, \"2026-03-20\")])\nconexao.commit()\n","sol":"def criar(nome, email):\n    cursor.execute(\"INSERT INTO Clientes (nome, email) VALUES (?, ?)\", (nome, email))\n    conexao.commit()\n    return cursor.lastrowid\n\ndef ler(id_):\n    cursor.execute(\"SELECT nome, email FROM Clientes WHERE id = ?\", (id_,))\n    return cursor.fetchone()\n\ndef atualizar(id_, email):\n    cursor.execute(\"UPDATE Clientes SET email = ? WHERE id = ?\", (email, id_))\n    conexao.commit()\n    return cursor.rowcount == 1\n\ndef excluir(id_):\n    cursor.execute(\"DELETE FROM Clientes WHERE id = ?\", (id_,))\n    conexao.commit()\n    return cursor.rowcount == 1","test":"n = criar(\"Eva Dias\", \"eva@x.com\")\nassert n == 5, \"lastrowid do novo cliente\"\nassert ler(n) == (\"Eva Dias\", \"eva@x.com\")\nassert ler(99) is None\nassert atualizar(n, \"eva@novo.com\") is True and ler(n)[1] == \"eva@novo.com\"\nassert atualizar(99, \"x\") is False\nassert excluir(n) is True and ler(n) is None\nassert excluir(n) is False\nassert not conexao.in_transaction, \"Faça commit nas alterações\"","h":["cursor.lastrowid tem o id do último INSERT","cursor.rowcount diz quantas linhas o UPDATE/DELETE afetou"]}]},{"name":"Automação Web (Selenium)","short":"navegador no piloto automático","cdesc":"controlar o navegador por código: abrir páginas, achar elementos e preencher formulários","map":"fluxo","src":"Intermediário • Módulo 29","groups":[["Começar",[["webdriver.Chrome()","abre o navegador controlado pelo Python"],["navegador.get(url)","acessa uma página"],["navegador.quit()","fecha o navegador ao final"]]],["Encontrar elementos",[["find_element(By.ID, ...)","1º elemento que atende; erro se não achar"],["find_elements(...)","lista com todos (vazia se nenhum)"],["By.*","ID, NAME, CLASS_NAME, TAG_NAME, CSS_SELECTOR, XPATH"]]],["Interagir",[["send_keys / clear","digitar e limpar campos"],["click()","botões, links, checkbox e radio"],["Select(...)","listas suspensas: select_by_visible_text / value"]]],["Ler informações",[[".text","texto visível do elemento"],["get_attribute('...')","value, href, class, data-*"],["Árvore HTML","buscar dentro de um elemento: el.find_element(...)"]]],["Robustez",[["Esperas","implicitly_wait / WebDriverWait + expected_conditions"],["iframe","switch_to.frame(...) e default_content()"],["Boas práticas","seletores estáveis (id), não guardar senha no código"]]]],"hot":["find_element devolve UM elemento (e dá erro se não achar); find_elements devolve uma LISTA.","Prefira By.ID quando existir: é o seletor mais estável.","By.CLASS_NAME aceita só UMA classe; para várias use CSS: '.produto.destaque'.",".text pega o texto visível; get_attribute('value') pega o que está digitado num input.","Elemento dentro de iframe só é encontrado depois de switch_to.frame(...).","Use esperas (WebDriverWait) em vez de time.sleep fixo quando a página carrega dados dinamicamente."],"trap":"send_keys ACRESCENTA texto ao que já existe no campo. Se o campo já vem preenchido, chame clear() antes.","examples":[["selenium_basico.py","from selenium import webdriver\nfrom selenium.webdriver.common.by import By\n\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\n\nnavegador.find_element(By.ID, \"email\").send_keys(\"ana@exemplo.com\")\nnavegador.find_element(By.ID, \"senha\").send_keys(senha)   # senha vinda de variável de ambiente\nnavegador.find_element(By.ID, \"entrar\").click()\n\nprodutos = navegador.find_elements(By.CLASS_NAME, \"produto\")\nfor p in produtos:\n    print(p.find_element(By.CLASS_NAME, \"nome\").text)\n\nnavegador.quit()"],["formulario.py","from selenium.webdriver.support.ui import Select\n\nSelect(navegador.find_element(By.ID, \"setor\")).select_by_visible_text(\"Tecnologia\")\nnavegador.find_element(By.ID, \"manha\").click()        # radio\nnavegador.find_element(By.XPATH, \"//input[@value='VT']\").click()\ncampo = navegador.find_element(By.ID, \"cpf\")\ncampo.clear()                                          # apaga o valor antigo\ncampo.send_keys(\"123.456.789-00\")"]],"ex":[{"t":"Abrir a página","p":"Crie o navegador com <code>webdriver.Chrome()</code> na variável <code>navegador</code>, acesse <code>https://loja.exemplo/login</code> e guarde o título da página em <code>titulo</code>.<br><small class='muted'>Aqui o Selenium é um <b>simulador</b> que roda no navegador; no seu PC o código é o mesmo.</small>","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/login\"] = \"\"\"\n<html><head><title>Login - Loja Exemplo</title></head><body>\n  <h1 class=\"titulo\">Acesso ao sistema</h1>\n  <form id=\"form-login\">\n    <input id=\"email\" name=\"email\" type=\"text\">\n    <input id=\"senha\" name=\"senha\" type=\"password\">\n    <input id=\"lembrar\" name=\"lembrar\" type=\"checkbox\" value=\"sim\">\n    <button id=\"entrar\" type=\"submit\">Entrar</button>\n  </form>\n  <a id=\"esqueci\" href=\"https://loja.exemplo/recuperar\">Esqueci a senha</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/recuperar\"] = \"\"\"\n<html><head><title>Recuperar senha</title></head><body><p id=\"msg\">Informe seu e-mail.</p></body></html>\"\"\"\n","sol":"from selenium import webdriver\n\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\ntitulo = navegador.title","test":"assert navegador.current_url == \"https://loja.exemplo/login\", \"Acesse a URL com navegador.get(...)\"\nassert titulo == \"Login - Loja Exemplo\", \"Use navegador.title para pegar o título\"","h":["from selenium import webdriver","navegador.get(url) e depois navegador.title"]},{"t":"Achar pela classe","p":"A página de login já está aberta em <code>navegador</code>. Encontre o título <code>&lt;h1&gt;</code> pela classe <code>titulo</code> e guarde o texto em <code>cabecalho</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/login\"] = \"\"\"\n<html><head><title>Login - Loja Exemplo</title></head><body>\n  <h1 class=\"titulo\">Acesso ao sistema</h1>\n  <form id=\"form-login\">\n    <input id=\"email\" name=\"email\" type=\"text\">\n    <input id=\"senha\" name=\"senha\" type=\"password\">\n    <input id=\"lembrar\" name=\"lembrar\" type=\"checkbox\" value=\"sim\">\n    <button id=\"entrar\" type=\"submit\">Entrar</button>\n  </form>\n  <a id=\"esqueci\" href=\"https://loja.exemplo/recuperar\">Esqueci a senha</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/recuperar\"] = \"\"\"\n<html><head><title>Recuperar senha</title></head><body><p id=\"msg\">Informe seu e-mail.</p></body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\n","sol":"cabecalho = navegador.find_element(By.CLASS_NAME, \"titulo\").text","test":"assert cabecalho == \"Acesso ao sistema\", \"Use find_element(By.CLASS_NAME, \\\"titulo\\\").text\"","h":["find_element(By.CLASS_NAME, ...)","O texto visível está em .text"]},{"t":"Preencher o login","p":"Com o login aberto, digite <code>usuario</code> no campo de id <code>email</code> e <code>senha</code> no campo de id <code>senha</code>. As duas variáveis já existem.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/login\"] = \"\"\"\n<html><head><title>Login - Loja Exemplo</title></head><body>\n  <h1 class=\"titulo\">Acesso ao sistema</h1>\n  <form id=\"form-login\">\n    <input id=\"email\" name=\"email\" type=\"text\">\n    <input id=\"senha\" name=\"senha\" type=\"password\">\n    <input id=\"lembrar\" name=\"lembrar\" type=\"checkbox\" value=\"sim\">\n    <button id=\"entrar\" type=\"submit\">Entrar</button>\n  </form>\n  <a id=\"esqueci\" href=\"https://loja.exemplo/recuperar\">Esqueci a senha</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/recuperar\"] = \"\"\"\n<html><head><title>Recuperar senha</title></head><body><p id=\"msg\">Informe seu e-mail.</p></body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\nusuario = \"ana@exemplo.com\"\nsenha = \"s3nh@\"\n","sol":"navegador.find_element(By.ID, \"email\").send_keys(usuario)\nnavegador.find_element(By.ID, \"senha\").send_keys(senha)","test":"assert navegador.find_element(By.ID, \"email\").get_attribute(\"value\") == \"ana@exemplo.com\", \"O campo email deve conter o usuário\"\nassert navegador.find_element(By.ID, \"senha\").get_attribute(\"value\") == \"s3nh@\", \"O campo senha deve conter a senha\"\nr = rodar(usuario=\"leo@x.com\", senha=\"123\")\nn = r[\"navegador\"]\nassert n.find_element(By.ID, \"email\").get_attribute(\"value\") == \"leo@x.com\", \"Use as variáveis usuario e senha, não textos fixos\"","h":["find_element(By.ID, \"email\")",".send_keys(usuario)"]},{"t":"Clicar em Entrar","p":"Preencha o e-mail com <code>usuario</code>, marque a caixa <b>lembrar</b> (id <code>lembrar</code>) e clique no botão <code>entrar</code>. O simulador registra o formulário enviado em <code>navegador.formularios_enviados</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/login\"] = \"\"\"\n<html><head><title>Login - Loja Exemplo</title></head><body>\n  <h1 class=\"titulo\">Acesso ao sistema</h1>\n  <form id=\"form-login\">\n    <input id=\"email\" name=\"email\" type=\"text\">\n    <input id=\"senha\" name=\"senha\" type=\"password\">\n    <input id=\"lembrar\" name=\"lembrar\" type=\"checkbox\" value=\"sim\">\n    <button id=\"entrar\" type=\"submit\">Entrar</button>\n  </form>\n  <a id=\"esqueci\" href=\"https://loja.exemplo/recuperar\">Esqueci a senha</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/recuperar\"] = \"\"\"\n<html><head><title>Recuperar senha</title></head><body><p id=\"msg\">Informe seu e-mail.</p></body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\nusuario = \"ana@exemplo.com\"\n","sol":"navegador.find_element(By.ID, \"email\").send_keys(usuario)\nnavegador.find_element(By.ID, \"lembrar\").click()\nnavegador.find_element(By.ID, \"entrar\").click()","test":"env = navegador.formularios_enviados\nassert env, \"O formulário não foi enviado: clique no botão entrar\"\nassert env[-1].get(\"email\") == usuario, \"Preencha o e-mail antes de clicar em Entrar\"\nassert env[-1].get(\"lembrar\") == \"sim\", \"Marque a caixa lembrar com .click() antes de enviar\"","h":["Checkbox também se marca com .click()","A ordem importa: preencha e marque ANTES de clicar em entrar"]},{"t":"Ler o link","p":"Guarde em <code>destino</code> o endereço (atributo <code>href</code>) do link de id <code>esqueci</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/login\"] = \"\"\"\n<html><head><title>Login - Loja Exemplo</title></head><body>\n  <h1 class=\"titulo\">Acesso ao sistema</h1>\n  <form id=\"form-login\">\n    <input id=\"email\" name=\"email\" type=\"text\">\n    <input id=\"senha\" name=\"senha\" type=\"password\">\n    <input id=\"lembrar\" name=\"lembrar\" type=\"checkbox\" value=\"sim\">\n    <button id=\"entrar\" type=\"submit\">Entrar</button>\n  </form>\n  <a id=\"esqueci\" href=\"https://loja.exemplo/recuperar\">Esqueci a senha</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/recuperar\"] = \"\"\"\n<html><head><title>Recuperar senha</title></head><body><p id=\"msg\">Informe seu e-mail.</p></body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/login\")\n","sol":"destino = navegador.find_element(By.ID, \"esqueci\").get_attribute(\"href\")","test":"assert destino == \"https://loja.exemplo/recuperar\", \"Use get_attribute(\\\"href\\\")\"","h":["Atributos HTML: get_attribute(\"nome\")","O texto do link (.text) não é o endereço"]},{"t":"Listar produtos","p":"Na página de produtos (já aberta), crie a lista <code>nomes</code> com o texto de todos os elementos de classe <code>nome</code>, na ordem da página.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"nomes = [el.text for el in navegador.find_elements(By.CLASS_NAME, \"nome\")]","test":"assert nomes == [\"Notebook\", \"Mouse\", \"Teclado\", \"Monitor\"], \"Use find_elements (no plural) e pegue o .text de cada um\"","h":["find_elements devolve uma lista","Percorra com for (ou list comprehension) pegando .text"]},{"t":"Busca dentro do elemento","p":"Para cada <code>div.produto</code>, pegue o nome e o preço (como <code>float</code>) <b>dentro do próprio card</b> e monte o dicionário <code>precos</code> no formato <code>{nome: preço}</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"precos = {}\nfor card in navegador.find_elements(By.CLASS_NAME, \"produto\"):\n    nome = card.find_element(By.CLASS_NAME, \"nome\").text\n    precos[nome] = float(card.find_element(By.CLASS_NAME, \"preco\").text)","test":"assert precos == {\"Notebook\": 3500.0, \"Mouse\": 80.0, \"Teclado\": 150.0, \"Monitor\": 1200.0}, \"Esperado {nome: preço float} para os 4 produtos\"","h":["Um elemento também tem find_element: card.find_element(...)","Converta o texto do preço com float()"]},{"t":"Seletor CSS","p":"Usando <code>By.CSS_SELECTOR</code>, guarde em <code>destaques</code> a lista com o <b>nome</b> dos produtos que têm as classes <code>produto</code> e <code>destaque</code> ao mesmo tempo.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"destaques = [el.text for el in navegador.find_elements(By.CSS_SELECTOR, \".produto.destaque .nome\")]","test":"assert destaques == [\"Mouse\", \"Monitor\"], \"Os destaques são Mouse e Monitor\"\nassert \"CSS_SELECTOR\" in codigo, \"Use By.CSS_SELECTOR\"","h":["Duas classes juntas, sem espaço: .produto.destaque","Espaço = descendente: \".produto.destaque .nome\""]},{"t":"Formulário com lista suspensa","p":"No cadastro (já aberto), digite <code>nome</code> no campo <code>nome</code>, escolha o setor <b>Tecnologia</b> pelo texto visível e o turno <b>manhã</b> (radio de id <code>manha</code>). Depois clique em <code>salvar</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://rh.exemplo/cadastro\"] = \"\"\"\n<html><head><title>Cadastro de Funcionário</title></head><body>\n  <form id=\"cadastro\">\n    <input id=\"nome\" name=\"nome\" type=\"text\">\n    <input id=\"cpf\" name=\"cpf\" type=\"text\" value=\"000.000.000-00\">\n    <select id=\"setor\" name=\"setor\">\n      <option value=\"\">-- escolha --</option>\n      <option value=\"fin\">Financeiro</option>\n      <option value=\"ti\">Tecnologia</option>\n      <option value=\"rh\">Recursos Humanos</option>\n    </select>\n    <input type=\"radio\" name=\"turno\" id=\"manha\" value=\"manha\">\n    <input type=\"radio\" name=\"turno\" id=\"tarde\" value=\"tarde\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vr\" value=\"VR\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vt\" value=\"VT\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"plano\" value=\"Plano de saúde\">\n    <textarea id=\"obs\" name=\"obs\"></textarea>\n    <button id=\"salvar\" type=\"submit\">Salvar</button>\n  </form>\n</body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import Select\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://rh.exemplo/cadastro\")\nnome = \"Bruna Lima\"\n","sol":"navegador.find_element(By.ID, \"nome\").send_keys(nome)\nSelect(navegador.find_element(By.ID, \"setor\")).select_by_visible_text(\"Tecnologia\")\nnavegador.find_element(By.ID, \"manha\").click()\nnavegador.find_element(By.ID, \"salvar\").click()","test":"f = navegador.formularios_enviados\nassert f, \"Clique em salvar para enviar o formulário\"\nassert f[-1][\"nome\"] == nome, \"Preencha o nome\"\nassert f[-1][\"setor\"] == \"ti\", \"Escolha Tecnologia com Select(...).select_by_visible_text\"\nassert f[-1].get(\"turno\") == \"manha\", \"Clique no radio de id manha\"","h":["Select(elemento).select_by_visible_text(\"Tecnologia\")","Radio button: .click()"]},{"t":"Corrigir campo preenchido","p":"O campo <code>cpf</code> já vem com <code>000.000.000-00</code>. Substitua pelo valor de <code>cpf</code> e guarde o valor final do campo em <code>valor_final</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://rh.exemplo/cadastro\"] = \"\"\"\n<html><head><title>Cadastro de Funcionário</title></head><body>\n  <form id=\"cadastro\">\n    <input id=\"nome\" name=\"nome\" type=\"text\">\n    <input id=\"cpf\" name=\"cpf\" type=\"text\" value=\"000.000.000-00\">\n    <select id=\"setor\" name=\"setor\">\n      <option value=\"\">-- escolha --</option>\n      <option value=\"fin\">Financeiro</option>\n      <option value=\"ti\">Tecnologia</option>\n      <option value=\"rh\">Recursos Humanos</option>\n    </select>\n    <input type=\"radio\" name=\"turno\" id=\"manha\" value=\"manha\">\n    <input type=\"radio\" name=\"turno\" id=\"tarde\" value=\"tarde\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vr\" value=\"VR\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vt\" value=\"VT\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"plano\" value=\"Plano de saúde\">\n    <textarea id=\"obs\" name=\"obs\"></textarea>\n    <button id=\"salvar\" type=\"submit\">Salvar</button>\n  </form>\n</body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://rh.exemplo/cadastro\")\ncpf = \"123.456.789-00\"\n","sol":"campo = navegador.find_element(By.ID, \"cpf\")\ncampo.clear()\ncampo.send_keys(cpf)\nvalor_final = campo.get_attribute(\"value\")","test":"assert valor_final == \"123.456.789-00\", \"O campo deve ter só o CPF novo. send_keys acrescenta: use clear() antes\"\nassert rodar(cpf=\"111.222.333-44\")[\"valor_final\"] == \"111.222.333-44\", \"Use a variável cpf\"","h":["send_keys acrescenta ao texto existente","campo.clear() antes de digitar"]},{"t":"Ler tabela HTML","p":"Leia a tabela <code>tabela-vendas</code> e monte o dicionário <code>vendas</code> <code>{mês: vendas (int)}</code>, ignorando a linha de cabeçalho.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"vendas = {}\ntabela = navegador.find_element(By.ID, \"tabela-vendas\")\nfor linha in tabela.find_elements(By.TAG_NAME, \"tr\")[1:]:\n    celulas = linha.find_elements(By.TAG_NAME, \"td\")\n    vendas[celulas[0].text] = int(celulas[1].text)","test":"assert vendas == {\"Jan\": 100, \"Fev\": 140, \"Mar\": 90}, \"Esperado {\\\"Jan\\\": 100, \\\"Fev\\\": 140, \\\"Mar\\\": 90}\"","h":["Linhas: find_elements(By.TAG_NAME, \"tr\"); pule a primeira com [1:]","Células: find_elements(By.TAG_NAME, \"td\")"]},{"t":"XPath por atributo","p":"Marque os benefícios cujos <b>values</b> estão na lista <code>escolhidos</code>, usando <b>XPath</b> (<code>//input[@value='...']</code>). Depois clique em <code>salvar</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://rh.exemplo/cadastro\"] = \"\"\"\n<html><head><title>Cadastro de Funcionário</title></head><body>\n  <form id=\"cadastro\">\n    <input id=\"nome\" name=\"nome\" type=\"text\">\n    <input id=\"cpf\" name=\"cpf\" type=\"text\" value=\"000.000.000-00\">\n    <select id=\"setor\" name=\"setor\">\n      <option value=\"\">-- escolha --</option>\n      <option value=\"fin\">Financeiro</option>\n      <option value=\"ti\">Tecnologia</option>\n      <option value=\"rh\">Recursos Humanos</option>\n    </select>\n    <input type=\"radio\" name=\"turno\" id=\"manha\" value=\"manha\">\n    <input type=\"radio\" name=\"turno\" id=\"tarde\" value=\"tarde\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vr\" value=\"VR\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"vt\" value=\"VT\">\n    <input type=\"checkbox\" name=\"beneficios\" id=\"plano\" value=\"Plano de saúde\">\n    <textarea id=\"obs\" name=\"obs\"></textarea>\n    <button id=\"salvar\" type=\"submit\">Salvar</button>\n  </form>\n</body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://rh.exemplo/cadastro\")\nescolhidos = [\"VR\", \"Plano de saúde\"]\n","sol":"for b in escolhidos:\n    navegador.find_element(By.XPATH, f\"//input[@value='{b}']\").click()\nnavegador.find_element(By.ID, \"salvar\").click()","test":"f = navegador.formularios_enviados\nassert f, \"Clique em salvar\"\nassert sorted(f[-1].get(\"beneficios\", [])) == [\"Plano de saúde\", \"VR\"], \"Marque exatamente os benefícios de escolhidos\"\nn = rodar(escolhidos=[\"VT\"])[\"navegador\"]\nassert n.formularios_enviados[-1].get(\"beneficios\") == \"VT\", \"Percorra a lista escolhidos\"\nassert \"XPATH\" in codigo, \"Use By.XPATH\"","h":["f-string no XPath: f\"//input[@value='{b}']\"","Use aspas simples dentro e duplas fora"]},{"t":"Conteúdo dentro de iframe","p":"A cotação está num <code>iframe</code> de id <code>quadro-cotacao</code>. Entre nele, leia o dólar (id <code>dolar</code>) como <code>float</code> em <code>dolar</code>, volte para a página principal e guarde o texto do <code>h1</code> (id <code>topo</code>) em <code>titulo</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://portal.exemplo/\"] = \"\"\"\n<html><head><title>Portal</title></head><body>\n  <h1 id=\"topo\">Portal do Cliente</h1>\n  <iframe id=\"quadro-cotacao\" src=\"https://portal.exemplo/cotacao\"></iframe>\n</body></html>\"\"\"\nPAGINAS[\"https://portal.exemplo/cotacao\"] = \"\"\"\n<html><body><span id=\"dolar\">5.43</span><span id=\"euro\">5.91</span></body></html>\"\"\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://portal.exemplo/\")\n","sol":"quadro = navegador.find_element(By.ID, \"quadro-cotacao\")\nnavegador.switch_to.frame(quadro)\ndolar = float(navegador.find_element(By.ID, \"dolar\").text)\nnavegador.switch_to.default_content()\ntitulo = navegador.find_element(By.ID, \"topo\").text","test":"assert dolar == 5.43, \"Entre no iframe com navegador.switch_to.frame(...) e leia o id dolar\"\nassert titulo == \"Portal do Cliente\", \"Volte com switch_to.default_content() antes de buscar o h1\"","h":["navegador.switch_to.frame(elemento_do_iframe)","Para voltar: navegador.switch_to.default_content()"]},{"t":"Espera explícita","p":"Use <code>WebDriverWait(navegador, 10)</code> com <code>EC.presence_of_element_located</code> para aguardar o elemento de id <code>vazio</code> na página do carrinho (clique no link que contém o texto <b>Carrinho</b>). Guarde o texto em <code>aviso</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"navegador.find_element(By.PARTIAL_LINK_TEXT, \"Carrinho\").click()\nel = WebDriverWait(navegador, 10).until(EC.presence_of_element_located((By.ID, \"vazio\")))\naviso = el.text","test":"assert navegador.current_url == \"https://loja.exemplo/carrinho\", \"Clique no link do carrinho (By.PARTIAL_LINK_TEXT)\"\nassert aviso == \"Seu carrinho está vazio\", \"Leia o texto do elemento retornado pela espera\"\nassert 10 in navegador.esperas, \"Use WebDriverWait(navegador, 10)\"","h":["O localizador vai como tupla: (By.ID, \"vazio\")","until(...) devolve o elemento encontrado"]},{"t":"Desafio: relatório de estoque","p":"Na página de produtos, crie a lista <code>sem_estoque</code> com os nomes de produtos com estoque 0 e o dicionário <code>valor_estoque</code> <code>{nome: preço × estoque}</code> só dos que têm estoque. No fim, feche o navegador com <code>quit()</code>.","s":"from simulador_web import PAGINAS\nPAGINAS[\"https://loja.exemplo/produtos\"] = \"\"\"\n<html><head><title>Produtos</title></head><body>\n  <h1>Catálogo</h1>\n  <div class=\"produto\" data-id=\"101\"><span class=\"nome\">Notebook</span> <span class=\"preco\">3500.00</span> <span class=\"estoque\">5</span></div>\n  <div class=\"produto destaque\" data-id=\"102\"><span class=\"nome\">Mouse</span> <span class=\"preco\">80.00</span> <span class=\"estoque\">0</span></div>\n  <div class=\"produto\" data-id=\"103\"><span class=\"nome\">Teclado</span> <span class=\"preco\">150.00</span> <span class=\"estoque\">12</span></div>\n  <div class=\"produto destaque\" data-id=\"104\"><span class=\"nome\">Monitor</span> <span class=\"preco\">1200.00</span> <span class=\"estoque\">3</span></div>\n  <table id=\"tabela-vendas\">\n    <tr><th>Mês</th><th>Vendas</th></tr>\n    <tr><td>Jan</td><td>100</td></tr>\n    <tr><td>Fev</td><td>140</td></tr>\n    <tr><td>Mar</td><td>90</td></tr>\n  </table>\n  <a class=\"link\" href=\"https://loja.exemplo/login\">Entrar</a>\n  <a class=\"link\" href=\"https://loja.exemplo/carrinho\">Carrinho (0)</a>\n</body></html>\"\"\"\nPAGINAS[\"https://loja.exemplo/login\"] = \"<html><head><title>Login</title></head><body></body></html>\"\nPAGINAS[\"https://loja.exemplo/carrinho\"] = \"<html><head><title>Carrinho</title></head><body><p id='vazio'>Seu carrinho está vazio</p></body></html>\"\nfrom selenium import webdriver\nfrom selenium.webdriver.common.by import By\nnavegador = webdriver.Chrome()\nnavegador.get(\"https://loja.exemplo/produtos\")\n","sol":"sem_estoque = []\nvalor_estoque = {}\nfor card in navegador.find_elements(By.CSS_SELECTOR, \"div.produto\"):\n    nome = card.find_element(By.CLASS_NAME, \"nome\").text\n    preco = float(card.find_element(By.CLASS_NAME, \"preco\").text)\n    qtd = int(card.find_element(By.CLASS_NAME, \"estoque\").text)\n    if qtd == 0:\n        sem_estoque.append(nome)\n    else:\n        valor_estoque[nome] = preco * qtd\nnavegador.quit()","test":"assert sem_estoque == [\"Mouse\"], \"Só o Mouse está sem estoque\"\nassert valor_estoque == {\"Notebook\": 17500.0, \"Teclado\": 1800.0, \"Monitor\": 3600.0}, \"valor = preço × estoque, só para estoque > 0\"\nassert navegador.fechado, \"Feche o navegador com navegador.quit()\"","h":["Converta preço com float() e estoque com int()","if qtd == 0 ... else ...; e navegador.quit() no final"]}]},{"name":"Web Scraping (BeautifulSoup)","short":"extrair dados de páginas","cdesc":"ler o HTML, encontrar tags por nome, classe e id, navegar na árvore e tratar dados faltantes","map":"radial","src":"Intermediário • Módulo 30","pkgs":["beautifulsoup4"],"groups":[["Fluxo",[["requests.get(url).text","baixa o HTML (no seu PC)"],["BeautifulSoup(html, \"html.parser\")","transforma em árvore navegável"],["Extrair e salvar","listas, dicionários, pandas, CSV"]]],["Encontrar",[["find(tag, class_=...)","o 1º que atende (ou None)"],["find_all(...)","lista com todos"],["select(\"css\")","seletor CSS: \".livro .nome\""]]],["Ler",[[".text / get_text(strip=True)","texto da tag"],["tag[\"href\"] / tag.get(\"href\")","atributos"],["attrs","dicionário de atributos"]]],["Navegar",[["parent / parents","subir na árvore"],["contents / children","filhos diretos"],["find_next / next_sibling","andar para os lados"]]],["Regras e cuidados",[["robots.txt e termos","respeite o site"],["Tags faltantes","find devolve None: trate antes de usar .text"],["Site dinâmico","conteúdo por JavaScript → Selenium"]]]],"hot":["class é palavra reservada: no find use class_=\"nome\".","find devolve UM elemento (ou None); find_all devolve uma lista.","get_text(strip=True) já tira espaços e quebras de linha.","Antes de usar .text, confira se o find não devolveu None.","Se o dado aparece só depois do JavaScript, o requests não vê: use Selenium."],"trap":"site.find(\"p\", class_=\"avaliacao\").text quebra (AttributeError: 'NoneType') quando o livro não tem avaliação. Teste se é None primeiro.","examples":[["raspagem.py","import requests\nfrom bs4 import BeautifulSoup\n\nresposta = requests.get(\"https://site-exemplo.com/livros\")\nsite = BeautifulSoup(resposta.text, \"html.parser\")\n\nfor livro in site.find_all(\"div\", class_=\"livro\"):\n    nome = livro.find(\"h2\", class_=\"nome\").get_text(strip=True)\n    preco = livro.find(\"p\", class_=\"preco\").get_text(strip=True)\n    print(nome, preco)"],["navegacao.py","titulo = site.find(id=\"titulo\").text\nlinks = [a[\"href\"] for a in site.find_all(\"a\")]\nnomes = [h.text for h in site.select(\"div.livro h2.nome\")]\n\nnota = site.find(\"p\", class_=\"avaliacao\")\nvalor = float(nota.text) if nota else None    # trata o dado faltante"]],"ex":[{"t":"Criar a sopa","p":"A variável <code>html</code> tem o código da página. Crie <code>site = BeautifulSoup(html, \"html.parser\")</code> e guarde o texto do <code>&lt;title&gt;</code> em <code>titulo</code>.<br><small class='muted'>No seu PC o HTML viria de <code>requests.get(url).text</code>.</small>","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\n","sol":"site = BeautifulSoup(html, \"html.parser\")\ntitulo = site.title.text","test":"assert titulo == \"Livraria Exemplo\"","h":["BeautifulSoup(html, \"html.parser\")","site.title.text"]},{"t":"Achar pelo id","p":"Guarde em <code>cabecalho</code> o texto do elemento de id <code>titulo</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"cabecalho = site.find(id=\"titulo\").text","test":"assert cabecalho == \"Mais vendidos\"","h":["site.find(id=\"...\")",".text pega o texto"]},{"t":"Todos os nomes","p":"Crie <code>nomes</code> com o texto de todos os <code>h2</code> de classe <code>nome</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"nomes = [h.text for h in site.find_all(\"h2\", class_=\"nome\")]","test":"assert nomes == [\"Python para Dados\", \"SQL na Prática\", \"Lógica de Programação\"]","h":["find_all(\"h2\", class_=\"nome\")","class_ com underline"]},{"t":"Links da página","p":"Crie <code>links</code> com o atributo <code>href</code> de todos os <code>&lt;a&gt;</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"links = [a[\"href\"] for a in site.find_all(\"a\")]","test":"assert links == [\"/ficcao\", \"/tecnologia\", \"https://outro.site/promo\"]","h":["Atributo: tag[\"href\"] ou tag.get(\"href\")","Percorra find_all(\"a\")"]},{"t":"Seletor CSS","p":"Use <code>site.select</code> para pegar o nome do(s) livro(s) com as classes <code>livro</code> e <code>destaque</code>, guardando em <code>destaques</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"destaques = [h.text for h in site.select(\"div.livro.destaque h2.nome\")]","test":"assert destaques == [\"SQL na Prática\"]\nassert \"select(\" in codigo","h":["select usa sintaxe CSS","\"div.livro.destaque h2.nome\""]},{"t":"Preço como número","p":"Crie <code>precos</code>: lista de floats a partir dos textos de preço (<code>R$ 89,90</code> → <code>89.9</code>).","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"precos = [float(p.text.replace(\"R$\", \"\").strip().replace(\".\", \"\").replace(\",\", \".\")) for p in site.find_all(\"p\", class_=\"preco\")]","test":"assert precos == [89.9, 59.9, 39.5]","h":["Tire o R$ e os espaços","Troque a vírgula decimal por ponto"]},{"t":"Dados de cada card","p":"Para cada <code>div.livro</code>, monte um dicionário com <code>nome</code>, <code>autor</code> e <code>isbn</code> (atributo <code>data-isbn</code>) e guarde todos na lista <code>livros</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"livros = []\nfor card in site.find_all(\"div\", class_=\"livro\"):\n    livros.append({\n        \"nome\": card.find(\"h2\", class_=\"nome\").get_text(strip=True),\n        \"autor\": card.find(\"span\", class_=\"autor\").get_text(strip=True),\n        \"isbn\": card[\"data-isbn\"],\n    })","test":"assert livros[0] == {\"nome\": \"Python para Dados\", \"autor\": \"Ana Lima\", \"isbn\": \"111\"}\nassert [l[\"isbn\"] for l in livros] == [\"111\", \"222\", \"333\"]","h":["Busque DENTRO do card: card.find(...)","card[\"data-isbn\"]"]},{"t":"Dado faltante","p":"Crie <code>avaliacoes</code>: dicionário <code>{nome: nota}</code> com a avaliação (float) de cada livro, ou <code>None</code> quando o livro não tiver avaliação.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"avaliacoes = {}\nfor card in site.find_all(\"div\", class_=\"livro\"):\n    nome = card.find(\"h2\", class_=\"nome\").text\n    nota = card.find(\"p\", class_=\"avaliacao\")\n    avaliacoes[nome] = float(nota.text) if nota else None","test":"assert avaliacoes == {\"Python para Dados\": 4.5, \"SQL na Prática\": 4.8, \"Lógica de Programação\": None}, \"O 3º livro não tem avaliação: use None\"","h":["find devolve None quando não acha","float(nota.text) if nota else None"]},{"t":"Tabela HTML","p":"Leia a tabela <code>vendas</code> e crie o dicionário <code>unidades</code> <code>{mês: int}</code>, pulando o cabeçalho.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"unidades = {}\nfor linha in site.find(id=\"vendas\").find_all(\"tr\")[1:]:\n    mes, qtd = [td.text for td in linha.find_all(\"td\")]\n    unidades[mes] = int(qtd)","test":"assert unidades == {\"Jan\": 120, \"Fev\": 95, \"Mar\": 143}","h":["find_all(\"tr\")[1:] pula o cabeçalho","Cada linha tem 2 <td>"]},{"t":"Subir na árvore (parent)","p":"Encontre o <code>span</code> com o autor <code>Leo Rocha</code> (use <code>string=</code>) e, subindo com <code>.parent</code>, guarde o <code>data-isbn</code> do card em <code>isbn_leo</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"autor = site.find(\"span\", string=\"Leo Rocha\")\nisbn_leo = autor.parent[\"data-isbn\"]","test":"assert isbn_leo == \"222\"\nassert \".parent\" in codigo","h":["find(\"span\", string=\"Leo Rocha\")","O card é o pai do span: .parent"]},{"t":"Links internos e externos","p":"Separe os links em <code>internos</code> (começam com <code>/</code>) e <code>externos</code> (começam com <code>http</code>). Monte também <code>completos</code> transformando os internos em URL completa com <code>urljoin(base, href)</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\nbase = \"https://livraria.exemplo\"\n","sol":"from urllib.parse import urljoin\nhrefs = [a[\"href\"] for a in site.find_all(\"a\")]\ninternos = [h for h in hrefs if h.startswith(\"/\")]\nexternos = [h for h in hrefs if h.startswith(\"http\")]\ncompletos = [urljoin(base, h) for h in internos]","test":"assert internos == [\"/ficcao\", \"/tecnologia\"] and externos == [\"https://outro.site/promo\"]\nassert completos == [\"https://livraria.exemplo/ficcao\", \"https://livraria.exemplo/tecnologia\"]","h":["startswith(\"/\") e startswith(\"http\")","from urllib.parse import urljoin"]},{"t":"Filtrar por preço","p":"Crie <code>baratos</code> com os nomes dos livros com preço menor ou igual a <code>limite</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\nlimite = 60\n","sol":"baratos = []\nfor card in site.select(\"div.livro\"):\n    preco = float(card.select_one(\".preco\").text.replace(\"R$\", \"\").strip().replace(\",\", \".\"))\n    if preco <= limite:\n        baratos.append(card.select_one(\".nome\").text)","test":"assert baratos == [\"SQL na Prática\", \"Lógica de Programação\"]\nassert rodar(limite=40)[\"baratos\"] == [\"Lógica de Programação\"], \"Use a variável limite\"","h":["Converta o preço em float primeiro","select_one devolve o 1º elemento do seletor"]},{"t":"Para o pandas","p":"Monte o DataFrame <code>df</code> com as colunas <code>nome</code>, <code>autor</code> e <code>preco</code> (float) de todos os livros, e ordene pelo preço (menor primeiro).","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\nimport pandas as pd\n","sol":"dados = []\nfor card in site.find_all(\"div\", class_=\"livro\"):\n    dados.append({\n        \"nome\": card.find(class_=\"nome\").text,\n        \"autor\": card.find(class_=\"autor\").text,\n        \"preco\": float(card.find(class_=\"preco\").text.replace(\"R$\", \"\").strip().replace(\",\", \".\")),\n    })\ndf = pd.DataFrame(dados).sort_values(\"preco\")","test":"assert list(df.columns) == [\"nome\", \"autor\", \"preco\"]\nassert df[\"nome\"].tolist() == [\"Lógica de Programação\", \"SQL na Prática\", \"Python para Dados\"]\nassert df[\"preco\"].tolist() == [39.5, 59.9, 89.9]","h":["Lista de dicionários → pd.DataFrame(lista)","sort_values(\"preco\")"]},{"t":"Função raspadora segura","p":"Crie <code>extrair(html)</code> que retorna a lista de <code>(nome, preço float)</code> dos livros. Se a página não tiver nenhum livro, retorne lista vazia; se um card não tiver preço, pule o card.","s":"from bs4 import BeautifulSoup\n","sol":"def extrair(html):\n    site = BeautifulSoup(html, \"html.parser\")\n    resultado = []\n    for card in site.find_all(\"div\", class_=\"livro\"):\n        nome = card.find(class_=\"nome\")\n        preco = card.find(class_=\"preco\")\n        if not nome or not preco:\n            continue\n        valor = float(preco.text.replace(\"R$\", \"\").strip().replace(\",\", \".\"))\n        resultado.append((nome.get_text(strip=True), valor))\n    return resultado","test":"h = '<div class=\"livro\"><h2 class=\"nome\">A</h2><p class=\"preco\">R$ 10,00</p></div><div class=\"livro\"><h2 class=\"nome\">B</h2></div>'\nassert extrair(h) == [(\"A\", 10.0)], \"Pule o card sem preço\"\nassert extrair(\"<p>vazio</p>\") == []","h":["Confira se nome e preco não são None","continue pula para o próximo card"]},{"t":"Desafio: relatório da vitrine","p":"Gere <code>relatorio</code> (dicionário) com: <code>qtd</code> (livros), <code>preco_medio</code> (2 casas), <code>mais_caro</code> (nome), <code>melhor_avaliado</code> (nome, ignorando sem avaliação) e <code>categorias</code> (texto dos links). Grave também <code>livros.csv</code> com <code>nome,preco</code>.","s":"from bs4 import BeautifulSoup\nhtml = \"\"\"\n<html><head><title>Livraria Exemplo</title></head>\n<body>\n  <h1 id=\"titulo\">Mais vendidos</h1>\n  <ul id=\"categorias\"><li><a href=\"/ficcao\">Ficção</a></li><li><a href=\"/tecnologia\">Tecnologia</a></li><li><a href=\"https://outro.site/promo\">Promoções</a></li></ul>\n  <div class=\"livro\" data-isbn=\"111\">\n    <h2 class=\"nome\">Python para Dados</h2><span class=\"autor\">Ana Lima</span>\n    <p class=\"preco\">R$ 89,90</p><p class=\"avaliacao\">4.5</p>\n  </div>\n  <div class=\"livro destaque\" data-isbn=\"222\">\n    <h2 class=\"nome\">SQL na Prática</h2><span class=\"autor\">Leo Rocha</span>\n    <p class=\"preco\">R$ 59,90</p><p class=\"avaliacao\">4.8</p>\n  </div>\n  <div class=\"livro\" data-isbn=\"333\">\n    <h2 class=\"nome\">Lógica de Programação</h2><span class=\"autor\">Bia Melo</span>\n    <p class=\"preco\">R$ 39,50</p>\n  </div>\n  <table id=\"vendas\">\n    <tr><th>Mês</th><th>Unidades</th></tr>\n    <tr><td>Jan</td><td>120</td></tr><tr><td>Fev</td><td>95</td></tr><tr><td>Mar</td><td>143</td></tr>\n  </table>\n</body></html>\"\"\"\nsite = BeautifulSoup(html, \"html.parser\")\n","sol":"import csv\nlivros = []\nfor card in site.find_all(\"div\", class_=\"livro\"):\n    nota = card.find(class_=\"avaliacao\")\n    livros.append({\n        \"nome\": card.find(class_=\"nome\").text,\n        \"preco\": float(card.find(class_=\"preco\").text.replace(\"R$\", \"\").strip().replace(\",\", \".\")),\n        \"nota\": float(nota.text) if nota else None,\n    })\navaliados = [l for l in livros if l[\"nota\"] is not None]\nrelatorio = {\n    \"qtd\": len(livros),\n    \"preco_medio\": round(sum(l[\"preco\"] for l in livros) / len(livros), 2),\n    \"mais_caro\": max(livros, key=lambda l: l[\"preco\"])[\"nome\"],\n    \"melhor_avaliado\": max(avaliados, key=lambda l: l[\"nota\"])[\"nome\"],\n    \"categorias\": [a.text for a in site.select(\"#categorias a\")],\n}\nwith open(\"livros.csv\", \"w\", newline=\"\", encoding=\"utf-8\") as f:\n    w = csv.writer(f)\n    w.writerow([\"nome\", \"preco\"])\n    for l in livros:\n        w.writerow([l[\"nome\"], l[\"preco\"]])","test":"assert relatorio == {\"qtd\": 3, \"preco_medio\": 63.1, \"mais_caro\": \"Python para Dados\", \"melhor_avaliado\": \"SQL na Prática\", \"categorias\": [\"Ficção\", \"Tecnologia\", \"Promoções\"]}\nassert open(\"livros.csv\", encoding=\"utf-8\").read().splitlines() == [\"nome,preco\", \"Python para Dados,89.9\", \"SQL na Prática,59.9\", \"Lógica de Programação,39.5\"]","h":["Monte primeiro uma lista de dicionários com tudo","max(lista, key=lambda l: l[\"preco\"])"]}]}]};
